(window.TRENER_PACKS=window.TRENER_PACKS||{})["zadanie-4"]={"id": "zadanie-4", "subject": "Химия", "title": "Задание 4 ЕГЭ по химии: химическая связь и кристаллические решётки с нуля до 100 баллов", "version": "25.11.2026", "konspekt": "zadanie-4", "codes": ["1.4"], "kod": {"p": [{"id": "p1", "t": "Электроотрицательность и карта видов связи", "x": "Атомы образуют химическую связь ради снижения энергии и завершения электронной оболочки. В таблице ФИПИ электроотрицательность (ЭО) растёт слева направо и снизу вверх — к фтору F. Два одинаковых неметалла дают ковалентную неполярную связь, два разных неметалла — ковалентную полярную, металл + неметалл (или катион аммония/алкиламмония + анион) — ионную.", "ref": "01.1"}, {"id": "p2", "t": "Обменный и донорно-акцепторный механизмы ковалентной связи", "x": "При обменном механизме каждый атом даёт по одному неспаренному электрону; при донорно-акцепторном донор предоставляет готовую неподелённую пару, а акцептор — свободную орбиталь. После образования все связи одного типа (например, четыре связи N−H в NH4^{+}) становятся полностью равноценными.", "ref": "02.1"}, {"id": "p3", "t": "Характеристики ковалентной связи и полярность молекулы", "x": "Одинарная связь состоит из 1 σ-связи, двойная — из 1 σ + 1 π, тройная — из 1 σ + 2 π. Чем выше кратность связи и меньше атомные радиусы, тем связь короче и прочнее (выше энергия). Полярность всей молекулы определяется её пространственной симметрией: симметричные молекулы с полярными связями (CO2, SO3, BF3, CH4, CCl4) в целом неполярны.", "ref": "03.1"}, {"id": "p4", "t": "Ионная и металлическая связь", "x": "Ионная связь — ненаправленное электростатическое притяжение катионов и анионов (отдельных молекул нет, кристаллы хрупкие). В одном ионном веществе могут сочетаться 2–3 типа связей. Металлическая связь действует только в простых веществах-металлах и сплавах за счёт «электронного газа», обеспечивая пластичность, блеск и электропроводность.", "ref": "04.1"}, {"id": "p5", "t": "Силы Ван-дер-Ваальса и водородная связь", "x": "Между любыми молекулами действуют силы Ван-дер-Ваальса, усиливающиеся с ростом молярной массы. Межмолекулярная водородная связь между собственными молекулами возникает только при наличии атома H, ковалентно связанного с F, O или N (связи H−F, H−O, H−N), резко повышая температуру кипения и растворимость в воде.", "ref": "05.1"}, {"id": "p6", "t": "Молекулярное и немолекулярное строение: четыре типа решёток", "x": "Молекулярное строение соответствует только молекулярной решётке (отдельные молекулы в узлах). Немолекулярное строение объединяет три типа кристаллических решёток: атомную (узлы — атомы), ионную (катионы и анионы) и металлическую (атомы-ионы металла + электронный газ).", "ref": "06.1"}, {"id": "p7", "t": "Зависимость физических свойств от типа решётки", "x": "Физические свойства определяются прочностью связей в узлах кристалла: молекулярная — легкоплавкость, летучесть, возгонка, диэлектрики; атомная — сверхтугоплавкость, твёрдость, нерастворимость (графит — исключение); ионная — тугоплавкость, хрупкость, ток проводят только расплав и раствор; металлическая — пластичность и электропроводность в твёрдом виде.", "ref": "07.1"}, {"id": "p8", "t": "Алгоритм «Двойной фильтр» для задания № 4 КИМ", "x": "Для каждого из пяти веществ выписывай формулу (переводя тривиальные и органические названия), затем независимо проверяй Фильтр 1 (тип решётки / строение) и Фильтр 2 (все виды химических связей). Всегда различай формулировки «с ковалентной связью» и «только с ковалентной связью».", "ref": "08.1"}], "z": [{"id": "z1", "x": "В солях аммония (NH4Cl, NH4NO3, (NH4)2SO4) и солях аминов ([CH3NH3]Cl) нет металлов, но есть ионная связь, ионная решётка (немолекулярное строение), ковалентная полярная связь и донорно-акцепторный механизм.", "sk": "ion_met", "ref": "04.8"}, {"id": "z2", "x": "В кислотных оксидах металлов в высших степенях окисления (CrO3, Mn2O7) связь ковалентная полярная, а не ионная.", "sk": "eo_map", "ref": "01.13"}, {"id": "z3", "x": "Ковалентная неполярная связь встречается в сложных веществах: пероксидах (H2O2, Na2O2, BaO2 — связь O−O), пирите (FeS2 — связь S−S), ацетиленидах (CaC2 — связь C≡C), гидразине (N2H4) и органике с цепью из ≥ 2 атомов C.", "sk": "cov_mech", "ref": "02.6"}, {"id": "z4", "x": "Ковалентной неполярной связи НЕТ в органике с одним атомом C (CH4, CH3OH, HCHO, HCOOH, HCOONa, CH3NH2, (NH2)2CO) и там, где атомы C разделены O или N (CH3−O−CH3, HCOOCH3, (CH3)2NH, (CH3)3N).", "sk": "cov_mech", "ref": "02.7"}, {"id": "z5", "x": "Твёрдый список ЕГЭ для донорно-акцепторного механизма: соли аммония (NH4^{+}), соли аминов, H3O^{+}, CO, O3, HNO3/нитраты/нитросоединения и комплексные соединения ([Al(OH)4]^{−} и др.). В молекулах NH3 и H2O донорно-акцепторной связи НЕТ!", "sk": "cov_mech", "ref": "02.15"}, {"id": "z6", "x": "Не путай похожие пары по полярности молекулы: CO2, SO3, BF3, CH4, CCl4 — неполярные молекулы (симметричные); H2O, H2S, SO2, NH3, CH3Cl — полярные молекулы (несимметричные или с неподелённой парой).", "sk": "cov_props", "ref": "03.14"}, {"id": "z7", "x": "Металлическая связь есть ТОЛЬКО в простых веществах-металлах и сплавах (сталь, латунь, бронза). В солях, оксидах и гидроксидах металлов (FeCl3, CuO, NaOH) металлической связи нет.", "sk": "ion_met", "ref": "04.14"}, {"id": "z8", "x": "Межмолекулярной водородной связи между собственными молекулами НЕТ в HCl, H2S, PH3, углеводородах, альдегидах, кетонах, простых и сложных эфирах, третичных аминах — в них нет прямой связи H−F, H−O или H−N.", "sk": "h_bond", "ref": "05.10"}, {"id": "z9", "x": "Короткий список атомной решётки для ЕГЭ: алмаз, графит, Si, B, Ge, красный и чёрный фосфор, SiO2 (кварц), SiC (карборунд), BN. У CO2, SiH4, белого фосфора (P4) и фуллерена (C60) решётка молекулярная.", "sk": "lattices", "ref": "06.7"}, {"id": "z10", "x": "Оксид алюминия Al2O3 (корунд) в рамках ЕГЭ относят к ИОННОЙ кристаллической решётке (амфотерный оксид металла), несмотря на высокую твёрдость — не путай его с атомным SiO2.", "sk": "lattices", "ref": "06.9"}, {"id": "z11", "x": "Твёрдые ионные соли (NaCl, KNO3) НЕ проводят электрический ток (ионы закреплены в узлах), а их расплавы и водные растворы проводят. Графит имеет атомную решётку, но мягкий и проводит ток.", "sk": "phys_props", "ref": "07.5"}, {"id": "z12", "x": "Способность легко возгоняться (сублимировать: сухой лёд CO2, иод I2, нафталин) — характерный маркер молекулярной кристаллической решётки.", "sk": "phys_props", "ref": "07.8"}, {"id": "z13", "x": "Не путай тривиальные названия: нашатырь = NH4Cl (ионная решётка, Д-А связь), нашатырный спирт = водный раствор NH3 (молекулярное строение, нет ионной и нет Д-А связи).", "sk": "double_filter", "ref": "08.7"}]}, "skills": [{"id": "eo_map", "name": "Электроотрицательность и карта связей", "ref": "01", "idea": "Без таблицы цифр определять направление роста ЭО по таблице ФИПИ и безошибочно распределять пары атомов по видам химической связи с учётом границ школьной модели ЕГЭ.", "pre": {"type": "one", "q": "В каком ряду химические элементы расположены в порядке ВОЗРАСТАНИЯ их электроотрицательности по таблице ФИПИ?", "o": ["Si → P → S → Cl", "F → O → N → C", "Cl → Br → I → F", "Na → K → Rb → Cs"], "a": 0, "ex": "В периоде слева направо электроотрицательность растёт: Si < P < S < Cl (движемся к фтору F).", "d": {"1": "От F к C мы движемся влево по 2-му периоду — ЭО убывает, а не возрастает.", "2": "В группе сверху вниз (Cl → Br → I) ЭО убывает, а затем скачкообразно растёт к F — ряд немонотонный.", "3": "В IA группе сверху вниз (Na → K → Rb → Cs) радиус растёт, а ЭО убывает."}}, "pair": {"type": "one", "cases": [["Оксид хрома(III) Cr2O3", "Амфотерный оксид металла в низкой/промежуточной с.о. → в модели ЕГЭ ионная связь"], ["Оксид хрома(VI) CrO3", "Кислотный оксид металла в высшей степени окисления (+6) → ковалентная полярная связь"]], "q": "Почему в школьной модели ЕГЭ оксиды одного и того же металла (Cr2O3 и CrO3) имеют разный преобладающий тип химической связи?", "o": ["При росте степени окисления металла (+3 → +6) резко усиливается его способность притягивать электроны, и связь с кислородом становится ковалентной полярной", "В CrO3 больше атомов кислорода, поэтому появляется ковалентная неполярная связь O−O", "Хром в CrO3 превращается в неметалл, поэтому в нём возникает металлическая связь", "Между любым металлом и кислородом в ЕГЭ всегда строго ионная связь без исключений"], "a": 0, "ex": "У металлов в высших степенях окисления (Cr^{+6} в CrO3, Mn^{+7} в Mn2O7) сильно выражены неметаллические свойства — их оксиды кислотные, а связи в них ковалентные полярные."}, "fade": {"q": "Восстанови правила определения типа химической связи по Периодической системе ФИПИ:", "steps": ["В таблице ФИПИ электроотрицательность растёт в периоде {слева направо|справа налево|сверху вниз}, а в группе — {снизу вверх|сверху вниз|не меняется}.", "Два одинаковых неметалла образуют {ковалентную неполярную|ковалентную полярную|ионную} связь, а два разных неметалла — {ковалентную полярную|ковалентную неполярную|металлическую} связь.", "Условие задания «выберите вещества С ковалентной полярной связью» {допускает|исключает|запрещает} одновременное присутствие ионной связи (например, в KOH и C2H5ONa)."]}, "bug": {"q": "Найди ошибочный шаг в определении связей для набора веществ (HF, NaCl, Mn2O7, NH4Cl):", "steps": ["В HF оба элемента — разные неметаллы, поэтому связь ковалентная полярная (несмотря на большую ΔЭО ≈ 1,8).", "В NaCl соединены типичный металл и неметалл — связь ионная.", "В Mn2O7 есть металл марганец и неметалл кислород, значит в нём строго ионная связь.", "В NH4Cl между катионом аммония и хлорид-ионом ионная связь, а внутри NH4^{+} — ковалентные полярные связи."], "bad": 2, "fix": "Mn2O7 — кислотный оксид металла в высшей степени окисления (+7), в модели ЕГЭ связь в нём ковалентная полярная (как и в CrO3).", "why": "Правило «металл + неметалл = ионная связь» имеет важное ограничение для кислотных оксидов металлов в высших степенях окисления (CrO3, Mn2O7)."}, "recall": {"q": "Назови по памяти 4 главных ориентира карты связей ЕГЭ без таблицы значений ЭО.", "points": ["Направление роста ЭО в таблице ФИПИ: слева направо по периоду и снизу вверх по группе (максимум у фтора F).", "Два одинаковых неметалла → ковалентная неполярная; два разных неметалла → ковалентная полярная.", "Металл + неметалл (соли, основания, основные/амфотерные оксиды) и NH4^{+}/алкиламмоний + анион → ионная связь; исключение — кислотные оксиды CrO3 и Mn2O7 (ковалентная полярная).", "«С ковалентной связью» ≠ «только с ковалентной связью»: в одном веществе часто присутствуют сразу 2–3 типа связей."]}}, {"id": "cov_mech", "name": "Ковалентная связь: обменный и донорно-акцепторный механизмы", "ref": "02", "idea": "Мгновенно находить скрытые ковалентные неполярные связи в сложных и органических веществах и безошибочно выделять вещества с донорно-акцепторным механизмом.", "pre": {"type": "one", "q": "В каком из перечисленных веществ ЕСТЬ ковалентная связь, образованная по донорно-акцепторному механизму?", "o": ["Угарный газ CO", "Аммиак NH3", "Вода H2O", "Углекислый газ CO2"], "a": 0, "ex": "В молекуле CO две связи C=O обменные, а третья образуется за счёт неподелённой пары кислорода (донор) и пустой 2p-орбитали углерода (акцептор).", "d": {"1": "В NH3 все три связи N−H обменные; донорно-акцепторная связь появляется только при образовании NH4^{+}.", "2": "В H2O обе связи O−H обменные; вода лишь потенциальный донор (Д-А связь возникает в H3O^{+}).", "3": "В CO2 (O=C=O) углерод в возбуждённом состоянии образует 4 обменные связи."}}, "pair": {"type": "one", "cases": [["Этанол C2H5OH (CH3−CH2−OH)", "Два атома углерода связаны напрямую друг с другом (C−C) → есть ковалентная неполярная связь"], ["Диметиловый эфир CH3−O−CH3", "Два атома углерода разделены атомом кислорода (только C−H и C−O) → неполярной связи НЕТ"]], "q": "Почему два изомера с одинаковой брутто-формулой C2H6O различаются по наличию ковалентной неполярной связи?", "o": ["Наличие ковалентной неполярной связи зависит от структурной формулы: нужно прямое соединение двух одинаковых атомов (C−C), а не просто индекс 2 при углероде", "В простых эфирах все связи становятся ионными из-за кислородного мостика", "В этаноле неполярная связь образуется между атомами водорода H−H", "В диметиловом эфире связь C−O неполярная, так как C и O стоят в одном периоде"], "a": 0, "ex": "Всегда рисуй структурную формулу: в C2H5OH есть прямая связь C−C (неполярная), а в CH3−O−CH3 атомы C не соединены друг с другом."}, "fade": {"q": "Заполни схему образования донорно-акцепторной связи в катионе аммония NH4⁺:", "steps": ["В молекуле аммиака NH3 атом азота имеет три обменные связи N−H и одну {неподелённую электронную пару|свободную 2d-орбиталь|валентную тройную связь}.", "При встрече с протоном H⁺ азот выступает как {донор|акцептор|окислитель}, а ион H⁺ (с пустой 1s⁰-орбиталью) — как {акцептор|донор|восстановитель}.", "После образования катиона NH4⁺ все четыре связи N−H становятся {полностью равноценными|разными по длине|ионными}, а валентность азота равна {IV|III|V}."]}, "bug": {"q": "Найди ошибочный шаг в поиске ковалентной неполярной связи в сложных веществах:", "steps": ["В пероксиде водорода H−O−O−H есть ковалентная неполярная связь O−O.", "В карбиде кальция CaC2 внутри аниона C2^{2−} есть тройная неполярная связь C≡C.", "В муравьиной кислоте HCOOH и диметиловом эфире CH3−O−CH3 есть ковалентная неполярная связь, так как это органические вещества.", "В пирите FeS2 внутри дисульфид-иона S2^{2−} присутствует неполярная связь S−S."], "bad": 2, "fix": "В HCOOH только один атом C, а в CH3−O−CH3 два атома C разделены кислородом — в обоих веществах связи C−C (и вообще неполярной связи) нет.", "why": "Нельзя ставить знак равенства между «органика» и «есть связь C−C»: обязательно проверяй, соединены ли атомы углерода напрямую."}, "recall": {"q": "Перечисли по памяти полный экзаменационный список ЕГЭ для донорно-акцепторного механизма (7 групп) и 2 главные ловушки.", "points": ["Соли аммония (NH4Cl, NH4NO3, (NH4)2SO4) и соли аминов ([CH3NH3]Cl, [C6H5NH3]Br).", "Ион гидроксония H3O^{+}.", "Угарный газ CO и озон O3.", "Азотная кислота HNO3, нитраты (KNO3), N2O5 и нитросоединения (C6H5NO2).", "Комплексные соединения с квадратными скобками: Na[Al(OH)4], K2[Zn(OH)4], [Ag(NH3)2]OH, K4[Fe(CN)6].", "Главные ловушки: в NH3, H2O, CO2 и O2 донорно-акцепторной связи НЕТ."]}}, {"id": "cov_props", "name": "Характеристики ковалентной связи: σ/π, длина, энергия, полярность", "ref": "03", "idea": "Считать σ- и π-связи, сравнивать длину и энергию связей по кратности и радиусам атомов и отличать полярность связи от полярности всей молекулы.", "pre": {"type": "one", "q": "Сколько σ-связей и π-связей содержится в одной молекуле углекислого газа CO2 (O=C=O)?", "o": ["2 σ-связи и 2 π-связи", "4 σ-связи и 0 π-связей", "2 σ-связи и 1 π-связь", "1 σ-связь и 2 π-связи"], "a": 0, "ex": "В молекуле O=C=O две двойные связи. Каждая двойная связь состоит из 1 σ + 1 π, итого 2 σ-связи и 2 π-связи.", "d": {"1": "Четыре σ-связи были бы при четырёх одинарных связях (как в CH4), но в CO2 связи двойные.", "2": "Забыта π-связь во второй двойной связи C=O.", "3": "1 σ + 2 π — это состав одной тройной связи (например, в N2 или CO), а не двух двойных."}}, "pair": {"type": "one", "cases": [["Сернистый газ SO2 (S^{+4})", "У серы осталась неподелённая пара → молекула уголковая → ПОЛЯРНАЯ"], ["Серный ангидрид SO3 (S^{+6})", "Неподелённых пар у серы нет → симметричный плоский треугольник → НЕПОЛЯРНАЯ"]], "q": "Почему молекула SO2 полярна, а молекула SO3 неполярна, хотя в обеих есть сильно полярные связи S=O?", "o": ["Из-за геометрии: в SO3 три одинаковые связи S=O расположены симметрично под 120° и гасят диполи друг друга, а в SO2 неподелённая пара изгибает молекулу", "В SO3 связи S=O становятся неполярными, так как сера в высшей степени окисления", "В SO2 есть водородная связь, делающая молекулу полярной", "Молекула SO3 имеет ионную связь, поэтому у неё нет дипольного момента"], "a": 0, "ex": "Полярность молекулы равна векторной сумме диполей всех связей. В симметричном треугольнике SO3 сумма векторов равна нулю; в изогнутой молекуле SO2 — не равна нулю."}, "fade": {"q": "Восстанови закономерности длины и энергии ковалентной связи:", "steps": ["В ряду галогеноводородов HF → HCl → HBr → HI радиус галогена {увеличивается|уменьшается|не меняется}, поэтому длина связи {растёт|уменьшается|остаётся постоянной}, а энергия связи {убывает|растёт|не меняется}.", "В ряду C−C → C=C → C≡C кратность связи растёт, поэтому длина связи {уменьшается|увеличивается|не меняется}, а энергия разрыва связи {возрастает|падает|обнуляется}.", "Связь, образованная перекрыванием орбиталей по линии центров ядер, называется {σ-связью|π-связью|водородной связью}; она {прочнее|слабее|длиннее} бокового перекрывания."]}, "bug": {"q": "Найди ошибочный шаг в определении полярности молекул (CO2, CH4, NH3, CCl4):", "steps": ["В CO2 связи C=O полярны, но молекула линейна (180°), поэтому молекула в целом неполярна.", "В CH4 и CCl4 центральный углерод связан с четырьмя одинаковыми атомами в правильном тетраэдре — молекулы неполярны.", "В NH3 три одинаковые связи N−H, значит молекула симметрична и неполярна, как BF3.", "Если заменить один атом H в метане на Cl (получив CH3Cl), симметрия нарушится и молекула станет полярной."], "bad": 2, "fix": "В отличие от плоского треугольника BF3, у азота в NH3 есть неподелённая электронная пара — она превращает молекулу в тригональную пирамиду, поэтому NH3 полярна.", "why": "Одинаковые внешние атомы дают неполярную молекулу только тогда, когда у центрального атома нет неподелённой пары, ломающей симметрию."}, "recall": {"q": "Перечисли по памяти 5 главных неполярных молекул с полярными связями и 5 главных полярных молекул для КИМ № 4.", "points": ["Неполярные молекулы с полярными связями: CO2, CS2 (линейные), SO3, BF3 (плоские треугольники), CH4, CCl4, SiH4, CF4 (правильные тетраэдры).", "Полярные молекулы: H2O, H2S, SO2 (уголковые), NH3, PH3, PCl3 (пирамидальные), HCl, HF, CO, CH3Cl (несимметричные).", "Кратность: одинарная = 1 σ; двойная = 1 σ + 1 π; тройная = 1 σ + 2 π.", "Короче и прочнее связь при меньшем радиусе атомов (HF прочнее HI) и большей кратности (C≡C прочнее C=C и C−C)."]}}, {"id": "ion_met", "name": "Ионная и металлическая связь: смешанные связи и «электронный газ»", "ref": "04", "idea": "Раскладывать любое ионное вещество на все присутствующие виды связей (включая соли аммония, органические соли, пероксиды, пирит, карбид кальция) и отличать металлическую связь от ионной.", "pre": {"type": "one", "q": "Какие виды химической связи присутствуют одновременно в этилате натрия C2H5ONa (демоверсия ФИПИ ЕГЭ-2027)?", "o": ["Ионная, ковалентная полярная и ковалентная неполярная", "Только ионная и ковалентная полярная", "Только ковалентная полярная и ковалентная неполярная", "Металлическая, ионная и ковалентная полярная"], "a": 0, "ex": "Строение CH3−CH2−O^{−} Na^{+}: ионная между O^{−} и Na^{+}, ковалентные полярные C−H и C−O, ковалентная неполярная C−C.", "d": {"1": "Упущена прямая связь C−C в этильном радикале CH3−CH2−.", "2": "Алкоголяты металлов — солеподобные вещества: между O^{−} и Na^{+} действует ионная связь.", "3": "Металлической связи в соединениях натрия нет — она бывает только в простом веществе Na и сплавах."}}, "pair": {"type": "one", "cases": [["Ионный кристалл NaCl", "При ударе слой ионов сдвигается → одноимённые заряды (+/+ и −/−) отталкиваются → кристалл раскалывается"], ["Металлический кристалл Cu", "При ударе слои ионов скользят → общий «электронный газ» перетекает и удерживает слои → металл гнётся"]], "q": "Почему ионные кристаллы хрупкие, а металлы пластичные и ковкие, хотя обе связи ненаправленные?", "o": ["В ионной решётке сдвиг слоя сталкивает одноимённые заряды (отталкивание), а в металле свободный «электронный газ» мгновенно перераспределяется и сохраняет притяжение", "В металлах действуют только слабые силы Ван-дер-Ваальса, поэтому слои легко двигаются", "В NaCl есть отдельные молекулы, которые рассыпаются при ударе", "В ионной решётке нет электронов, а в металле нет положительных ионов"], "a": 0, "ex": "Жёсткое чередование +/− в ионном кристалле приводит к отталкиванию при малейшем сдвиге; в металле море делокализованных электронов «смазывает» смещение слоёв."}, "fade": {"q": "Разложи все связи в трёх классических ловушках ЕГЭ (NH4NO3, Na2O2, CaCl2):", "steps": ["В хлориде кальция CaCl2 присутствуют {только ионные связи|ионная и ковалентная полярная|ионная и ковалентная неполярная}.", "В пероксиде натрия Na2O2 между Na⁺ и O2²⁻ связь {ионная|металлическая|ковалентная полярная}, а внутри иона [O−O]²⁻ — {ковалентная неполярная|ковалентная полярная|донорно-акцепторная}.", "В нитрате аммония NH4NO3 между NH4⁺ и NO3⁻ связь {ионная|ковалентная неполярная|водородная}, а внутри обоих ионов — {ковалентные полярные (в том числе по Д-А механизму)|только обменные неполярные|металлические}."]}, "bug": {"q": "Найди ошибочный шаг в анализе химических связей веществ (NH4Cl, FeS2, FeCl3, бронза):", "steps": ["В нашатыре NH4Cl есть ионная связь (между NH4^{+} и Cl^{−}) и ковалентные полярные связи внутри NH4^{+}.", "В пирите FeS2 есть ионная связь и ковалентная неполярная связь S−S в ионе S2^{2−}.", "В хлориде железа(III) FeCl3 присутствует металлическая связь, так как в формуле есть металл железо.", "В бронзе (сплаве меди и олова) действует металлическая связь."], "bad": 2, "fix": "В FeCl3 (соли металла) металлической связи нет — она существует только в простых веществах-металлах и сплавах.", "why": "Наличие атома металла в формуле соли, оксида или гидроксида указывает на ионную, а не на металлическую связь."}, "recall": {"q": "Назови 4 комбинации связей в ионных веществах ЕГЭ и по 2 примера на каждую.", "points": ["Только ионная: бинарные соединения с одноатомными ионами (NaCl, CaCl2, MgO, Al2O3, Al4C3, NaH).", "Ионная + ковалентная полярная: щёлочи (KOH), кислородсодержащие соли (Na2SO4, KNO3), соли аммония (NH4Cl, NH4NO3), соли аминов ([CH3NH3]Cl), формиат/метилат натрия (HCOONa, CH3ONa).", "Ионная + ковалентная неполярная: пероксиды металлов (Na2O2, BaO2), ацетилениды (CaC2), пирит (FeS2).", "Ионная + ковалентная полярная + ковалентная неполярная: соли/алкоголяты/феноляты с ≥ 2 атомами C (C2H5ONa, CH3COONa, C6H5ONa, CH3COONH4)."]}}, {"id": "h_bond", "name": "Водородная связь и силы Ван-дер-Ваальса", "ref": "05", "idea": "Применять правило «трёх богатырей» (F, O, N) и мгновенно отсекать приманки, где есть кислород/азот и водород, но нет прямой связи H−F, H−O или H−N.", "pre": {"type": "one", "q": "Между молекулами какого из перечисленных веществ в чистом виде ОБРАЗУЮТСЯ водородные связи?", "o": ["Метиламин CH3NH2", "Триметиламин (CH3)3N", "Диметиловый эфир CH3−O−CH3", "Ацетон CH3−CO−CH3"], "a": 0, "ex": "В первичном амине CH3NH2 есть две прямые связи N−H, поэтому между его молекулами образуются водородные связи.", "d": {"1": "В третичном амине (CH3)3N при атоме азота нет ни одного атома водорода — все H связаны только с C.", "2": "В простом эфире CH3−O−CH3 нет связи O−H (все H при углероде).", "3": "В чистом ацетоне CH3−CO−CH3 нет связи O−H (водородные связи возможны только с водой в растворе, но не между собственными молекулами)."}}, "pair": {"type": "one", "cases": [["Вода H2O (M = 18 г/моль)", "Жидкость при н.у., t_кип = +100 °C — прочные межмолекулярные водородные связи"], ["Сероводород H2S (M = 34 г/моль)", "Газ при н.у., t_кип = −60 °C — только слабые силы Ван-дер-Ваальса"]], "q": "Почему более лёгкая вода H2O кипит на 160 градусов выше, чем почти вдвое более тяжёлый сероводород H2S?", "o": ["Кислород стоит во 2-м периоде, имеет высокую ЭО и малый радиус, образуя прочные водородные связи между молекулами H2O; сера в H2S водородных связей не образует", "У воды ионная кристаллическая решётка, а у сероводорода — молекулярная", "Связь O−H слабее связи S−H, поэтому вода легче ассоциируется", "В сероводороде действуют ковалентные неполярные связи"], "a": 0, "ex": "Правило F, O, N: только три самых электроотрицательных элемента малого радиуса образуют выраженные водородные связи; у S (3-й период) их нет."}, "fade": {"q": "Проверь условия образования водородной связи и действия сил Ван-дер-Ваальса:", "steps": ["В ряду галогенов F2 → Cl2 → Br2 → I2 температура кипения растёт, потому что с ростом молярной массы усиливаются {силы Ван-дер-Ваальса|водородные связи|ионные связи}.", "Межмолекулярная водородная связь между собственными молекулами возникает только тогда, когда атом H ковалентно связан с {F, O или N|Cl, S или P|C, Si или B}.", "Карбоновые кислоты кипят выше спиртов сопоставимой массы, потому что образуют прочные циклические {димеры за счёт двух водородных связей|ионные кристаллы|полимеры с атомной решёткой}."]}, "bug": {"q": "Найди ошибочный шаг в отборе веществ с межмолекулярными водородными связями:", "steps": ["В спиртах (C2H5OH), феноле (C6H5OH) и карбоновых кислотах (HCOOH) есть группа −OH → водородные связи есть.", "В фтороводороде HF, аммиаке NH3 и пероксиде водорода H2O2 есть связи H−F, H−N, H−O → водородные связи есть.", "В хлороводороде HCl и уксусном альдегиде CH3CHO есть электроотрицательные атомы Cl и O, значит между их молекулами тоже образуются водородные связи.", "В белках водородные связи действуют внутри молекулы, удерживая α-спираль вторичной структуры."], "bad": 2, "fix": "Ни в HCl (хлор не входит в тройку F, O, N), ни в чистом CH3CHO (нет прямой связи O−H) межмолекулярных водородных связей нет.", "why": "Недостаточно просто «видеть O или галоген» в формуле — нужна именно прямая ковалентная связь H−F, H−O или H−N."}, "recall": {"q": "Перечисли 5 классов с межмолекулярной водородной связью и 5 главных «приманок», где её НЕТ.", "points": ["ЕСТЬ: HF, H2O, H2O2, NH3; кислородсодержащие кислоты (H2SO4, HNO3, H3PO4); спирты и фенолы; карбоновые кислоты; первичные и вторичные амины, аминокислоты, углеводы.", "НЕТ (главные приманки): HCl/HBr/HI и H2S/PH3; простые эфиры (CH3−O−CH3); сложные эфиры (HCOOCH3, CH3COOC2H5); альдегиды (HCHO, CH3CHO) и кетоны (CH3COCH3); третичные амины ((CH3)3N) и углеводороды.", "Тонкость на 100 баллов: чистый ацетон и эфиры не образуют H-связей друг с другом, но могут образовывать H-связи с молекулами воды (отсюда растворимость)."]}}, {"id": "lattices", "name": "Молекулярное и немолекулярное строение: 4 типа решёток", "ref": "06", "idea": "Мгновенно делить вещества на молекулярные и немолекулярные и безошибочно определять тип решётки для всех аллотропов и спорных соединений ЕГЭ.", "pre": {"type": "one", "q": "Какие типы кристаллических решёток относятся к НЕМОЛЕКУЛЯРНОМУ строению?", "o": ["Атомная, ионная и металлическая", "Только ионная", "Только атомная и металлическая", "Молекулярная и атомная"], "a": 0, "ex": "Молекулярное строение — это только молекулярная решётка. Все три остальных типа (атомная, ионная, металлическая) не содержат отдельных молекул и относятся к немолекулярному строению.", "d": {"1": "Самая частая ошибка КИМ № 4 — забывать атомную (SiO2, C, Si) и металлическую (Fe, Cu) решётки.", "2": "Ионные кристаллы состоят из ионов, а не из молекул — они тоже немолекулярного строения.", "3": "Молекулярная решётка соответствует молекулярному, а не немолекулярному строению."}}, "pair": {"type": "one", "cases": [["Белый фосфор (P4)", "Состоит из отдельных молекул-тетраэдров P4 → МОЛЕКУЛЯРНАЯ решётка (t_пл = +44 °C)"], ["Красный фосфор (P_красн.)", "Полимерные цепи из атомов фосфора → АТОМНАЯ решётка (тугоплавок, нелетуч)"]], "q": "Почему две аллотропные модификации одного элемента (белый и красный фосфор) относятся к разным типам строения?", "o": ["Белый фосфор построен из отдельных замкнутых молекул P4 (молекулярное строение), а красный — из непрерывного полимерного каркаса атомов (атомная решётка, немолекулярное строение)", "В красном фосфоре возникает ионная связь", "Белый фосфор — это металл с металлической решёткой", "В белом фосфоре ковалентная полярная связь, а в красном — неполярная"], "a": 0, "ex": "В обоих аллотропах ковалентная неполярная связь P−P, но разное пространственное устройство узлов кристалла: молекулы P4 vs атомный полимер."}, "fade": {"q": "Классифицируй по канону ЕГЭ-2027 пять коварных веществ по типу кристаллической решётки:", "steps": ["Углекислый газ CO2 в твёрдом состоянии (сухой лёд) имеет {молекулярную|атомную|ионную} решётку, а кварц SiO2 — {атомную|молекулярную|ионную}.", "Силан SiH4 имеет {молекулярную|атомную|металлическую} решётку, а карборунд SiC — {атомную|молекулярную|ионную}.", "Оксид алюминия Al2O3 и хлорид аммония NH4Cl в ЕГЭ относятся к {ионной|атомной|молекулярной} кристаллической решётке ({немолекулярное|молекулярное|газообразное} строение)."]}, "bug": {"q": "Найди ошибочный шаг в определении кристаллических решёток:", "steps": ["Алмаз и графит имеют атомную решётку, а фуллерен C60 — молекулярную.", "Оксид кремния(IV) SiO2 и бор B имеют атомную кристаллическую решётку.", "Поскольку оксид алюминия Al2O3 (корунд) очень твёрдый и не растворяется в воде, в ЕГЭ его относят к атомной кристаллической решётке.", "Все соли (включая NH4Cl, C2H5ONa и CH3COONa) имеют ионную кристаллическую решётку."], "bad": 2, "fix": "В рамках ЕГЭ оксид алюминия Al2O3 (как амфотерный оксид металла) относят строго к ионной кристаллической решётке.", "why": "Нельзя определять решётку Al2O3 только по твёрдости: в школьной модели ЕГЭ все основные и амфотерные оксиды металлов — ионные."}, "recall": {"q": "Назови по памяти весь короткий список веществ с атомной кристаллической решёткой для ЕГЭ и 4 главные аллотропные/формульные ловушки.", "points": ["Простые вещества с атомной решёткой: C (алмаз, графит), Si, B, Ge, красный и чёрный фосфор.", "Сложные вещества с атомной решёткой: SiO2 (кварц, кремнезём), SiC (карборунд), BN (нитрид бора), Si3N4.", "Ловушки: белый фосфор P4 и фуллерен C60 — молекулярные; силан SiH4 и SiCl4 — молекулярные (не всё с Si атомное!).", "Ловушки: CO2 — молекулярная, SiO2 — атомная, Al2O3 — ионная; соли аммония (NH4Cl) и органические соли (C2H5ONa) — ионные."]}}, {"id": "phys_props", "name": "Физические свойства веществ и тип кристаллической решётки", "ref": "07", "idea": "Расшифровывать описания физических свойств в условии задания № 4 (тугоплавкость, возгонка, электропроводность расплава/твёрдого тела, хрупкость) в конкретный тип решётки.", "pre": {"type": "one", "q": "Неизвестное твёрдое вещество X имеет высокую температуру плавления (801 °C), хрупкое, не проводит электрический ток в твёрдом состоянии, но хорошо проводит его в расплаве и водном растворе. Какова его кристаллическая решётка?", "o": ["Ионная", "Атомная", "Молекулярная", "Металлическая"], "a": 0, "ex": "Визитная карточка ионной решётки: высокая t_пл, хрупкость, диэлектрик в твёрдом виде (ионы закреплены), но проводник в расплаве и водном растворе (ионы свободны).", "d": {"1": "Вещества с атомной решёткой нерастворимы в воде и не проводят ток в расплаве.", "2": "Молекулярные вещества легкоплавкие и не проводят ток в расплаве.", "3": "Металлы пластичны и отлично проводят ток уже в твёрдом состоянии."}}, "pair": {"type": "one", "cases": [["Алмаз (атомная решётка, sp³)", "Трёхмерный жёсткий каркас → рекордная твёрдость, диэлектрик"], ["Графит (атомная решётка, sp²)", "Прочные слои, между слоями слабые силы Ван-дер-Ваальса + подвижные π-электроны → мягкий, проводит ток, но тугоплавкий"]], "q": "Почему графит оставляет след на бумаге и проводит электрический ток, хотя, как и алмаз, имеет атомную кристаллическую решётку?", "o": ["У графита слоистое строение: внутри слоёв прочные ковалентные связи и свободные π-электроны (проводимость и тугоплавкость), а между слоями слабые силы (слои легко сдвигаются)", "У графита на самом деле металлическая кристаллическая решётка", "Графит состоит из отдельных молекул C6, как молекулярный кристалл", "В графите есть примеси ионов натрия, переносящие заряд"], "a": 0, "ex": "Слоистая атомная структура графита объясняет сочетание трёх свойств: сверхвысокой температуры плавления (как у атомной решётки), мягкости и электропроводности."}, "fade": {"q": "Переведи физические свойства из условий ЕГЭ на язык кристаллических решёток:", "steps": ["Способность легко возгоняться (сублимировать, как сухой лёд CO2 и иод I2) характерна для {молекулярной|атомной|ионной} решётки.", "Твёрдая поваренная соль NaCl электрический ток {не проводит|проводит отлично|проводит только на свету}, но её расплав и водный раствор ток {проводят|не проводят|проводят хуже льда}.", "Чистый жидкий HCl ток {не проводит|проводит как металл|имеет ионную решётку}, а водный раствор HCl (соляная кислота) проводит за счёт {электролитической диссоциации на ионы|металлической связи|перехода в атомную решётку}."]}, "bug": {"q": "Найди ошибочный шаг в сопоставлении свойств и кристаллических решёток:", "steps": ["Вещества с атомной решёткой (SiO2, SiC, алмаз) практически нерастворимы в воде и имеют очень высокие температуры плавления.", "Металлы обладают высокой электро- и теплопроводностью как в твёрдом состоянии, так и в расплаве.", "Все вещества с металлической кристаллической решёткой обязательно очень твёрдые и имеют температуру плавления выше 1000 °C.", "Низкая температура плавления, летучесть и наличие запаха указывают на молекулярную кристаллическую решётку."], "bad": 2, "fix": "Температуры плавления и твёрдость металлов сильно различаются: Na и K режутся ножом и плавятся ниже 100 °C, Ga тает в руке (+29,8 °C), а ртуть Hg жидкая уже при −38,8 °C.", "why": "Металлическую решётку распознают по электропроводности в твёрдом виде, пластичности и металлическому блеску, а не по «обязательной сверхтугоплавкости»."}, "recall": {"q": "Назови 4 «ключа-свойства», по которым в задании № 4 мгновенно угадывается каждая из четырёх решёток.", "points": ["Молекулярная: низкие t_пл и t_кип, летучесть, запах, возгонка (I2, CO2), не проводит ток в твёрдом виде и расплаве.", "Атомная: сверхвысокие t_пл, очень высокая твёрдость, нелетучесть, нерастворимость в воде (исключение по мягкости и проводимости — графит).", "Ионная: высокие t_пл, твёрдость + хрупкость, ток НЕ проводит в твёрдом виде, но проводит в расплаве и растворе.", "Металлическая: пластичность, ковкость, металлический блеск, электропроводность в твёрдом и жидком виде (t_пл от −39 °C у Hg до +3422 °C у W)."]}}, {"id": "double_filter", "name": "Алгоритм «Двойной фильтр» и тривиальные названия КИМ № 4", "ref": "08", "idea": "Переводить тривиальные и органические названия в формулы и безошибочно отбирать ровно 2 вещества по двум независимым критериям КИМ № 4 за 40 секунд.", "pre": {"type": "one", "q": "В задании № 4 просят: «Выберите два вещества, в которых присутствуют ТОЛЬКО ковалентные полярные связи». Какое из веществ нужно СРАЗУ вычеркнуть, хотя в нём есть ковалентные полярные связи?", "o": ["Гидроксид калия KOH", "Сернистый газ SO2", "Метан CH4", "Формальдегид HCHO"], "a": 0, "ex": "В KOH есть ковалентная полярная связь O−H, но помимо неё есть ИОННАЯ связь K^{+}–OH^{−}, что нарушает жёсткий фильтр «ТОЛЬКО ковалентные полярные».", "d": {"1": "В SO2 только связи S=O — все они ковалентные полярные.", "2": "В CH4 только связи C−H — все они ковалентные полярные.", "3": "В HCHO только один атом C, связи C−H и C=O — все они ковалентные полярные."}}, "pair": {"type": "one", "cases": [["Нашатырь (NH4Cl)", "Соль аммония → ионная решётка, ионная + ковалентная полярная + Д-А связь"], ["Нашатырный спирт (водный раствор NH3)", "Раствор аммиака → молекулярное строение, ковалентная полярная + H-связи, нет ионной и нет Д-А"]], "q": "Почему подмена «нашатыря» на «нашатырный спирт» в задании № 4 гарантированно приводит к 0 баллов?", "o": ["Это разные вещества: нашатырь — ионная соль NH4Cl с донорно-акцепторной связью, а нашатырный спирт — водный раствор молекулярного NH3 без ионной и Д-А связи", "Нашатырный спирт — это органический спирт C2H5OH с неполярной связью C−C", "Нашатырь имеет атомную решётку, а нашатырный спирт — металлическую", "Это одно и то же вещество, различие только в агрегатном состоянии"], "a": 0, "ex": "Тривиальные названия-двойники — классический капкан ЕГЭ: нашатырь = NH4Cl, нашатырный спирт = водный раствор NH3."}, "fade": {"q": "Примени двойной фильтр к тривиальным названиям КИМ № 4:", "steps": ["Пирит (железный колчедан) имеет формулу {FeS2|FeS|CuFeS2}, ионную решётку и скрытую {ковалентную неполярную связь S−S|ковалентную полярную связь|водородную связь}.", "Карборунд — это {SiC|CaC2|Al4C3} с {атомной|ионной|молекулярной} решёткой, тогда как карбид кальция CaC2 имеет {ионную|атомную|молекулярную} решётку.", "Жёлтая кровяная соль K4[Fe(CN)6] содержит ионную связь, ковалентную полярную (с π-связями в CN⁻) и связь по {донорно-акцепторному|водородному|металлическому} механизму."]}, "bug": {"q": "Найди ошибочный шаг в решении задания № 4 («Выберите два вещества немолекулярного строения, в которых есть ковалентная неполярная связь» из ряда: H2O2, Na2O2, SiO2, CaC2, P4):", "steps": ["Переводим в формулы и проверяем Фильтр 1 (немолекулярное строение): подходят Na2O2 (ионная), SiO2 (атомная) и CaC2 (ионная); H2O2 и P4 — молекулярные, вычёркиваем.", "Проверяем Фильтр 2 (наличие ковалентной неполярной связи) среди оставшихся трёх веществ.", "В Na2O2 есть связь O−O (неполярная) → подходит; в SiO2 связи Si−O (ковалентные неполярные, так как решётка атомная) → подходит.", "В CaC2 внутри иона C2^{2−} есть тройная неполярная связь C≡C → подходит."], "bad": 2, "fix": "В SiO2 (кварце) решётка действительно атомная, но соединены РАЗНЫЕ неметаллы (Si и O), поэтому связи там ковалентные ПОЛЯРНЫЕ! Верный ответ: Na2O2 и CaC2.", "why": "Атомная решётка не означает «неполярная связь»: в простых атомных веществах (C, Si, B, красный P) связь неполярная, а в сложных (SiO2, SiC, BN) — ковалентная полярная."}, "recall": {"q": "Назови 5 шагов алгоритма «Двойной фильтр» и 4 главные проверки последних 10 секунд перед записью ответа № 4.", "points": ["Выписать формулу (для органики — структурную!) каждого из 5 веществ.", "Проверить Фильтр 1 (тип решётки / строение) для всех 5 веществ и вычеркнуть неподходящие.", "Проверить Фильтр 2 (все виды связей: ионная, полярная, неполярная, Д-А, H-связь, π-связь) для оставшихся.", "Перечитать кванторы в условии: «С ковалентной связью» (допускает ионную) vs «ТОЛЬКО с ковалентной связью».", "Убедиться, что выбраны ровно 2 цифры (порядок не важен, но 1 балл даётся только за точное совпадение обеих цифр)."]}}], "figs": {}, "tab": [{"id": "t_cov_mech", "t": "Ковалентная связь: скрытые неполярные связи и донорно-акцепторный механизм", "k": "Вещество", "km": "веществом", "ref": "02.14", "n": 4, "lv3": ["NH3 (аммиак)", "CH3−O−CH3 (диметиловый эфир)", "CO (угарный газ)", "O3 (озон)", "NH4Cl (хлорид аммония)", "Na[Al(OH)4] (тетрагидроксоалюминат натрия)"], "cols": [{"t": "Ковалентная неполярная связь", "sk": "cov_mech", "n": 4, "q": "Есть ли ковалентная неполярная связь в веществе {x}?", "m": "наличием ковалентной неполярной связи", "mq": "Выберите {k} вещества, для которых наличие ковалентной неполярной связи — «{v}»:"}, {"t": "Донорно-акцепторный механизм (ЕГЭ)", "sk": "cov_mech", "n": 4, "q": "Присутствует ли связь по донорно-акцепторному механизму в веществе {x}?", "m": "наличием донорно-акцепторного механизма", "mq": "Выберите {k} вещества, для которых наличие Д-А механизма — «{v}»:"}, {"t": "Конкретная связь / особенность", "sk": "cov_mech", "n": 4, "q": "Какая особенность ковалентных связей характерна для вещества {x}?", "m": "особенностью ковалентных связей"}], "rows": [["H2O2 (пероксид водорода)", "Да", "Нет", "Есть неполярная связь O−O; все связи обменные"], ["CaC2 (карбид кальция)", "Да", "Нет", "Тройная неполярная связь C≡C в анионе C2²⁻; Д-А нет"], ["CH3−O−CH3 (диметиловый эфир)", "Нет", "Нет", "Атомы C разделены O (связи C−C нет); все связи обменные"], ["NH3 (аммиак)", "Нет", "Нет", "Только полярные обменные связи N−H (Д-А появляется лишь в NH4⁺)"], ["NH4Cl (хлорид аммония)", "Нет", "Да", "Д-А связь N → H⁺ внутри катиона NH4⁺ + ионная связь с Cl⁻"], ["CO (угарный газ)", "Нет", "Да", "Тройная связь C≡O: две обменные + одна Д-А (O → C)"], ["O3 (озон)", "Да", "Да", "Неполярная связь между атомами O + Д-А (центральный O → крайний O)"], ["Na[Al(OH)4] (тетрагидроксоалюминат натрия)", "Нет", "Да", "Д-А связи лигандов OH⁻ с Al³⁺ внутри комплексного иона"]], "rw": {"CH3−O−CH3 (диметиловый эфир)": "Два атома C разделены атомом O — прямой связи C−C нет.", "NH3 (аммиак)": "Ловушка! В NH3 нет Д-А связи — она возникает только при присоединении H⁺ в NH4⁺.", "CO (угарный газ)": "Две обменные связи + одна Д-А (O → C) образуют тройную связь C≡O."}}, {"id": "t_polarity", "t": "Геометрия и полярность молекул с ковалентными полярными связями", "k": "Молекула", "km": "молекулой", "ref": "03.12", "n": 4, "lv3": ["CO2", "SO3", "SO2", "BF3", "NH3", "CH3Cl"], "cols": [{"t": "Геометрия молекулы", "sk": "cov_props", "n": 4, "q": "Какую пространственную геометрию имеет молекула {x}?", "m": "геометрией молекулы"}, {"t": "Полярность молекулы в целом", "sk": "cov_props", "n": 4, "q": "Полярна ли в целом молекула {x}?", "m": "полярностью молекулы в целом", "mq": "Выберите {k} молекулы с характеристикой «{v}»:"}], "rows": [["CO2", "Линейная (180°, симметричная)", "Неполярная (диполи гасятся)"], ["H2O", "Уголковая (104,5°, 2 неподелённые пары)", "Полярная (диполи складываются)"], ["SO3", "Плоский симметричный треугольник (120°)", "Неполярная (диполи гасятся)"], ["SO2", "Уголковая (1 неподелённая пара у S)", "Полярная (диполи складываются)"], ["BF3", "Плоский симметричный треугольник (120°)", "Неполярная (диполи гасятся)"], ["NH3", "Тригональная пирамида (1 неподелённая пара)", "Полярная (диполи складываются)"], ["CH4", "Правильный тетраэдр (109,5°, 4 одинаковых H)", "Неполярная (диполи гасятся)"], ["CH3Cl", "Несимметричный тетраэдр (3 H и 1 Cl)", "Полярная (диполи не гасятся)"]], "rw": {"CO2": "Связи C=O полярные, но линейная симметрия (180°) полностью обнуляет дипольный момент.", "SO3": "В отличие от SO2, у серы в SO3 нет неподелённой пары — плоский симметричный треугольник.", "BF3": "В отличие от NH3, у бора нет неподелённой пары — молекула плоская и неполярная."}}, {"id": "t_mixed_bonds", "t": "Смешанные химические связи в ионных и металлических веществах", "k": "Вещество", "km": "веществом", "ref": "04.7", "n": 4, "lv3": ["NH4NO3 (нитрат аммония)", "Na2O2 (пероксид натрия)", "FeS2 (пирит)", "C2H5ONa (этилат натрия)", "HCOONa (формиат натрия)"], "cols": [{"t": "Комбинация видов связи", "sk": "ion_met", "n": 4, "q": "Какая комбинация видов химической связи присутствует в веществе {x}?", "m": "комбинацией видов связи", "mq": "Выберите {k} вещества с набором связей «{v}»:"}, {"t": "Скрытая особенность в ЕГЭ", "sk": "ion_met", "n": 4, "q": "Какая ключевая особенность связей отличает вещество {x} в КИМ № 4?", "m": "ключевой особенностью связей"}], "rows": [["CaCl2 (хлорид кальция)", "Только ионная", "Оба иона одноатомные (Ca²⁺ и Cl⁻), ковалентных связей нет"], ["KOH (гидроксид калия)", "Ионная + ковалентная полярная", "Внутри гидроксогруппы OH⁻ есть ковалентная полярная связь O−H"], ["NH4NO3 (нитрат аммония)", "Ионная + ковалентная полярная", "Ионная связь без металла + Д-А механизм в обоих ионах"], ["Na2O2 (пероксид натрия)", "Ионная + ковалентная неполярная", "Внутри пероксид-иона [O−O]²⁻ неполярная связь O−O, полярных нет"], ["FeS2 (пирит)", "Ионная + ковалентная неполярная", "Внутри дисульфид-иона [S−S]²⁻ неполярная связь S−S"], ["C2H5ONa (этилат натрия)", "Ионная + ковалентная полярная + ковалентная неполярная", "Сразу 3 связи: O⁻Na⁺ (ион.), C−H/C−O (пол.) и C−C (непол.)"], ["HCOONa (формиат натрия)", "Ионная + ковалентная полярная", "Только 1 атом C → неполярной связи C−C нет!"], ["Fe (железо)", "Только металлическая", "Простое вещество-металл: катионы + обобществлённый электронный газ"]], "rw": {"NH4NO3 (нитрат аммония)": "Два атома N находятся в разных ионах (NH4⁺ и NO3⁻), поэтому связи N−N нет!", "C2H5ONa (этилат натрия)": "Главный пример демоверсии ЕГЭ-2027: ионная решётка + все три вида связей.", "HCOONa (формиат натрия)": "В отличие от ацетата CH3COONa, в формиате только один углерод — связи C−C нет."}}, {"id": "t_hbonds", "t": "Межмолекулярные водородные связи между собственными молекулами", "k": "Вещество", "km": "веществом", "ref": "05.8", "n": 4, "lv3": ["H2S (сероводород)", "CH3−O−CH3 (диметиловый эфир)", "CH3COCH3 (чистый ацетон)", "(CH3)3N (триметиламин)", "CH3COOH (уксусная кислота)"], "cols": [{"t": "Есть ли H-связи между своими молекулами", "sk": "h_bond", "n": 4, "q": "Образуются ли водородные связи между собственными молекулами вещества {x}?", "m": "наличием межмолекулярных водородных связей", "mq": "Выберите {k} вещества, для которых верно: «{v}»:"}, {"t": "Причина по правилу F, O, N", "sk": "h_bond", "n": 4, "q": "Чем объясняется наличие или отсутствие межмолекулярных водородных связей в {x}?", "m": "причиной наличия или отсутствия H-связей"}], "rows": [["H2O (вода)", "Да", "Есть прямые ковалентные связи H−O и неподелённые пары у O"], ["H2S (сероводород)", "Нет", "Сера (3-й период) не входит в тройку F, O, N"], ["C2H5OH (этанол)", "Да", "Есть гидроксильная группа −O−H"], ["CH3−O−CH3 (диметиловый эфир)", "Нет", "Все атомы H связаны с C, прямой связи O−H нет"], ["CH3COOH (уксусная кислота)", "Да", "Есть группа −COOH с прямой связью O−H (образует димеры)"], ["CH3COCH3 (чистый ацетон)", "Нет", "Кетон: все атомы H связаны с C, прямой связи O−H нет"], ["CH3NH2 (метиламин)", "Да", "Первичный амин: есть прямые связи N−H"], ["(CH3)3N (триметиламин)", "Нет", "Третичный амин: при атоме азота нет атомов H"]], "rw": {"CH3−O−CH3 (диметиловый эфир)": "Газ при н.у. (−24 °C), тогда как его изомер этанол — жидкость (+78 °C).", "(CH3)3N (триметиламин)": "У первичных и вторичных аминов есть N−H (H-связи есть), у третичных — нет."}}, {"id": "t_lattices", "t": "Строение и кристаллическая решётка спорных веществ (канон ЕГЭ-2027)", "k": "Вещество", "km": "веществом", "ref": "06.7", "n": 4, "lv3": ["SiO2 (кварц)", "Белый фосфор (P4)", "Красный фосфор", "Фуллерен (C60)", "Al2O3 (корунд)", "NH4Cl (нашатырь)", "SiH4 (силан)"], "cols": [{"t": "Тип кристаллической решётки", "sk": "lattices", "n": 4, "q": "Какой тип кристаллической решётки имеет вещество {x} (в твёрдом состоянии)?", "m": "типом кристаллической решётки", "mq": "Выберите {k} вещества с решёткой: «{v}»:"}, {"t": "Строение (молекулярное / немолекулярное)", "sk": "lattices", "n": 4, "q": "К какому типу строения относится вещество {x}?", "m": "типом строения", "mq": "Выберите {k} вещества, имеющие «{v}»:"}], "rows": [["SiO2 (кварц)", "Атомная", "Немолекулярное строение"], ["CO2 (сухой лёд)", "Молекулярная", "Молекулярное строение"], ["Белый фосфор (P4)", "Молекулярная", "Молекулярное строение"], ["Красный фосфор", "Атомная", "Немолекулярное строение"], ["Алмаз (C)", "Атомная", "Немолекулярное строение"], ["Фуллерен (C60)", "Молекулярная", "Молекулярное строение"], ["Al2O3 (корунд)", "Ионная", "Немолекулярное строение"], ["NH4Cl (нашатырь)", "Ионная", "Немолекулярное строение"], ["SiH4 (силан)", "Молекулярная", "Молекулярное строение"], ["Cu (медь)", "Металлическая", "Немолекулярное строение"]], "rw": {"Al2O3 (корунд)": "В ЕГЭ амфотерный оксид металла Al2O3 относится к ИОННОЙ решётке, а не к атомной!", "SiH4 (силан)": "Не каждое вещество с кремнием имеет атомную решётку: SiH4 — газ с молекулярной решёткой.", "Белый фосфор (P4)": "Молекулы-тетраэдры P4 → молекулярная; красный фосфор → атомная."}}, {"id": "t_props", "t": "Сводная карта физических свойств четырёх кристаллических решёток", "k": "Тип решётки", "km": "типом решётки", "ref": "07.3", "n": 4, "lv3": ["Атомная", "Ионная", "Металлическая"], "cols": [{"t": "Температуры плавления и летучесть", "sk": "phys_props", "n": 4, "q": "Какие температуры плавления и летучесть характерны для решётки «{x}»?", "m": "температурой плавления и летучестью"}, {"t": "Механические свойства", "sk": "phys_props", "n": 4, "q": "Какие механические свойства характерны для решётки «{x}»?", "m": "механическими свойствами"}, {"t": "Электропроводность", "sk": "phys_props", "n": 4, "q": "Как ведут себя вещества с решёткой «{x}» в отношении электрического тока?", "m": "электропроводностью"}], "rows": [["Молекулярная", "Низкие t_пл и t_кип, летучие, способны к возгонке", "Мягкие, легко растираются", "Не проводят в твёрдом виде и расплаве (растворы кислот — проводят)"], ["Атомная", "Сверхвысокие t_пл (>1000–3500 °C), нелетучие", "Очень твёрдые и прочные (исключение — слоистый графит)", "Диэлектрики или полупроводники (исключение — графит проводит)"], ["Ионная", "Высокие t_пл (300–2500 °C), нелетучие", "Твёрдые, но хрупкие при ударе", "Твёрдые НЕ проводят; расплав и водный раствор — проводят"], ["Металлическая", "Широкий диапазон t_пл (от Hg −39 °C до W +3422 °C), нелетучие", "Пластичные, ковкие, металлический блеск", "Отлично проводят ток и в твёрдом состоянии, и в расплаве"]], "rw": {"Ионная": "Главная ловушка № 4: в твёрдом виде ионы закреплены (тока нет), в расплаве и растворе свободны (ток идёт).", "Атомная": "Графит — единственное исключение по мягкости и электропроводности внутри атомной решётки."}}, {"id": "t_trivial", "t": "Тривиальные названия КИМ № 4: формула и решётка", "k": "Тривиальное название", "km": "тривиальным названием", "ref": "08.7", "n": 4, "lv3": ["Карборунд", "Пирит (железный колчедан)", "Нашатырь", "Нашатырный спирт", "Корунд (глинозём)"], "cols": [{"t": "Химическая формула", "sk": "double_filter", "n": 4, "q": "Какая формула соответствует тривиальному названию «{x}»?", "m": "химической формулой"}, {"t": "Тип решётки (в ЕГЭ)", "sk": "double_filter", "n": 4, "q": "Какой тип кристаллической решётки имеет вещество «{x}»?", "m": "типом кристаллической решётки", "mq": "Выберите {k} вещества, имеющие решётку «{v}»:"}], "rows": [["Кварц (кремнезём)", "SiO2", "Атомная"], ["Карборунд", "SiC", "Атомная"], ["Пирит (железный колчедан)", "FeS2", "Ионная"], ["Нашатырь", "NH4Cl", "Ионная"], ["Нашатырный спирт", "NH3·H2O (водный раствор NH3)", "Молекулярная"], ["Аммиачная селитра", "NH4NO3", "Ионная"], ["Корунд (глинозём)", "Al2O3", "Ионная"], ["Сухой лёд", "CO2 (тв.)", "Молекулярная"], ["Карбамид (мочевина)", "(NH2)2CO", "Молекулярная"]], "rw": {"Нашатырь": "NH4Cl — ионная решётка + Д-А связь. Не путать с нашатырным спиртом!", "Пирит (железный колчедан)": "FeS2 — ионная решётка + скрытая ковалентная неполярная связь S−S."}}], "rx": [{"id": "rx_na_cation", "sk": "ion_met", "ref": "04.3", "n": 4, "lvl": 1, "half": true, "l": ["Na"], "r": ["Na^{+}", "e⁻"], "c": [1, 1, 1], "if": "образование катиона натрия при формировании ионной связи (отдача 1 внешнего электрона)", "why": "Атом натрия (3s¹) отдаёт единственный внешний электрон и превращается в устойчивый катион Na^{+} с оболочкой неона."}, {"id": "rx_cl_anion", "sk": "ion_met", "ref": "04.3", "n": 4, "lvl": 1, "half": true, "l": ["Cl", "e⁻"], "r": ["Cl^{−}"], "c": [1, 1, 1], "if": "образование хлорид-иона при формировании ионной связи (присоединение 1 электрона)", "why": "Атом хлора (3s²3p⁵) принимает 1 электрон, завершая внешний энергетический уровень до октета (Cl^{−})."}], "seq": [{"id": "sq_polarity_row", "sk": "cov_props", "ref": "03.8", "n": 4, "lvl": 2, "q": "Расположите химические связи в порядке ВОЗРАСТАНИЯ их полярности (от наименее полярной к наиболее полярной по таблице ФИПИ):", "items": ["H−C (ΔЭО наименьшая)", "H−N", "H−O", "H−F (ΔЭО наибольшая среди водородных связей неметаллов)"], "why": "По 2-му периоду слева направо ЭО растёт (C < N < O < F), поэтому разность ΔЭО с водородом монотонно увеличивается."}, {"id": "sq_hx_energy", "sk": "cov_props", "ref": "03.8", "n": 4, "lvl": 3, "q": "Расположите галогеноводороды в порядке УБЫВАНИЯ длины связи (и одновременного ВОЗРАСТАНИЯ энергии/прочности связи):", "items": ["HI (самый большой радиус I → самая длинная и слабая связь)", "HBr", "HCl", "HF (самый малый радиус F → самая короткая и прочная связь)"], "why": "Снизу вверх по VIIА группе радиус галогена уменьшается, ядра сближаются, длина связи падает, а энергия разрыва связи растёт."}, {"id": "sq_lattice_tree", "sk": "lattices", "ref": "08.3", "n": 4, "lvl": 2, "q": "Установите правильный порядок проверок в дереве решений для определения типа кристаллической решётки любого вещества:", "items": ["Проверить, не является ли вещество простым веществом-металлом или сплавом (если да → металлическая)", "Проверить наличие ионной связи: металл + неметалл (кроме CrO3, Mn2O7) или катион аммония/алкиламмония (если да → ионная)", "Сверить вещество с коротким списком атомных решёток: C(алм/граф), Si, B, Ge, красный P, SiO2, SiC, BN (если да → атомная)", "Если все три проверки дали «нет» → отнести вещество к молекулярной решётке (молекулярному строению)"], "why": "Такой порядок исключает ошибки с солями аммония, Al2O3 и редкими атомными веществами за 3 секунды."}, {"id": "sq_double_filter_steps", "sk": "double_filter", "ref": "08.1", "n": 4, "lvl": 2, "q": "Установите оптимальную последовательность действий алгоритма «Двойной фильтр» при решении задания № 4 КИМ ЕГЭ-2027:", "items": ["Выписать химическую (для органики — структурную) формулу каждого из 5 предложенных веществ", "Выделить в условии два независимых фильтра и обратить внимание на слова «с» или «только с»", "Применить Фильтр 1 (тип решётки или строение) ко всем 5 веществам и вычеркнуть неподходящие", "Применить Фильтр 2 (все виды связей, Д-А, H-связи, π-связи) к оставшимся кандидатам", "Убедиться, что оба фильтра прошли ровно 2 вещества, и записать две цифры в бланк"], "why": "Раздельная проверка двух фильтров на выписанных формулах полностью устраняет главную причину потери балла в № 4."}], "facts": [{"id": "f_eo_bonds", "sk": "eo_map", "ref": "01.13", "n": 4, "lvl": 2, "t": "Электроотрицательность и границы видов связи в ЕГЭ", "s": [["В Периодической системе ФИПИ электроотрицательность растёт слева направо по периоду и снизу вверх по группе, достигая максимума у фтора F.", "В Периодической системе электроотрицательность растёт сверху вниз по группе и справа налево по периоду.", "Фтор F — самый электроотрицательный элемент; движение к нему (вправо и вверх) увеличивает ЭО."], ["В кислотных оксидах металлов в высших степенях окисления (CrO3, Mn2O7) химическая связь ковалентная полярная.", "В оксидах CrO3 и Mn2O7 связь строго ионная, так как они содержат атомы металлов.", "Высокая степень окисления (+6, +7) смещает свойства к неметаллическим — связи в CrO3 и Mn2O7 ковалентные полярные."], ["В одном сложном веществе (например, в KOH, NH4NO3 или C2H5ONa) могут одновременно присутствовать два или три вида химической связи.", "В любом химическом веществе может существовать только один вид химической связи.", "В сложных солях и основаниях ионная связь между ионами сочетается с ковалентными связями внутри сложных ионов."], ["В молекуле фтороводорода HF связь ковалентная полярная, так как оба элемента являются разными неметаллами.", "В молекуле HF связь ионная, так как разность электроотрицательностей фтора и водорода велика.", "В школьной модели ЕГЭ два разных неметалла (в том числе H и F) образуют ковалентную полярную связь."], ["Формулировка КИМ № 4 «вещества с ковалентной полярной связью» включает вещества, где помимо ковалентной есть и ионная связь (например, KOH).", "Формулировка «вещества с ковалентной полярной связью» запрещает выбирать любые ионные соли и щёлочи.", "Ионные вещества исключаются только при наличии строгого слова «ТОЛЬКО с ковалентной связью»."]]}, {"id": "f_cov_da", "sk": "cov_mech", "ref": "02.15", "n": 4, "lvl": 3, "t": "Ковалентная неполярная связь и донорно-акцепторный механизм", "s": [["В молекулах аммиака NH3 и воды H2O донорно-акцепторной связи НЕТ — все связи в них образованы по обменному механизму.", "В молекулах аммиака NH3 и воды H2O есть связи, образованные по донорно-акцепторному механизму.", "NH3 и H2O лишь потенциальные доноры; Д-А связь возникает при образовании ионов NH4^{+} и H3O^{+}."], ["В угарном газе CO, озоне O3, азотной кислоте HNO3 и хлориде аммония NH4Cl присутствует ковалентная связь, образованная по донорно-акцепторному механизму.", "В углекислом газе CO2 и кислороде O2 есть ковалентная связь, образованная по донорно-акцепторному механизму.", "В CO2 (O=C=O) и O2 (O=O) все связи обменные; Д-А механизм есть в CO и O3."], ["В пероксиде водорода H2O2, пирите FeS2 и карбиде кальция CaC2 присутствует ковалентная неполярная связь.", "Ковалентная неполярная связь бывает исключительно в простых веществах-неметаллах.", "Скрытые неполярные связи O−O, S−S и C≡C — классическая ловушка КИМ № 4 среди сложных веществ."], ["В диметиловом эфире CH3−O−CH3, метилформиате HCOOCH3 и муравьиной кислоте HCOOH ковалентной неполярной связи НЕТ.", "В любом органическом веществе с двумя и более атомами углерода обязательно есть ковалентная неполярная связь C−C.", "Если два атома углерода разделены кислородом или азотом (CH3−O−CH3, (CH3)2NH), прямой связи C−C нет."], ["После образования донорно-акцепторной связи в катионе NH4^{+} все четыре связи N−H становятся полностью равноценными по длине и энергии.", "В катионе NH4^{+} четвёртая (донорно-акцепторная) связь длиннее и слабее трёх обменных связей N−H.", "Способ образования связи не влияет на её свойства после замыкания — все 4 связи в NH4^{+} идентичны."]]}, {"id": "f_sigma_pol", "sk": "cov_props", "ref": "03.14", "n": 4, "lvl": 3, "t": "σ/π-связи, длина, энергия и полярность молекул", "s": [["Молекулы CO2, SO3, BF3, CH4 и CCl4 содержат ковалентные полярные связи, но в целом являются НЕПОЛЯРНЫМИ из-за пространственной симметрии.", "Если в молекуле все связи ковалентные полярные, то вся молекула обязательно является полярной.", "В симметричных молекулах векторы диполей связей компенсируют друг друга."], ["Молекула SO2 полярна (уголковая, есть неподелённая пара у S), а молекула SO3 неполярна (плоский симметричный треугольник).", "Молекулы SO2 и SO3 обе неполярны, так как состоят из одинаковых элементов S и O.", "Неподелённая пара в SO2 изгибает молекулу и создаёт дипольный момент."], ["В ряду этан (C−C) → этилен (C=C) → ацетилен (C≡C) длина углерод-углеродной связи уменьшается, а энергия разрыва связи растёт.", "Чем выше кратность связи, тем связь длиннее и легче полностью разрывается на атомы.", "Большее число общих электронных пар сильнее стягивает ядра: связь короче и прочнее."], ["Любая одинарная связь — это 1 σ-связь, двойная — 1 σ + 1 π, тройная — 1 σ + 2 π; при этом π-связь рвётся легче σ-связи.", "Тройная связь состоит из трёх σ-связей, поэтому она самая прочная.", "По линии центров ядер может лежать только одна σ-связь; вторая и третья связи — боковые π-связи."], ["В ряду HF → HCl → HBr → HI длина связи увеличивается, а энергия связи уменьшается.", "Самая короткая и прочная связь в ряду галогеноводородов — это связь H−I.", "У иода наибольший атомный радиус, поэтому связь H−I самая длинная и слабая (HI — сильнейшая кислота)."]]}, {"id": "f_ion_met", "sk": "ion_met", "ref": "04.8", "n": 4, "lvl": 3, "t": "Ионная, металлическая и смешанные связи", "s": [["В солях аммония (NH4Cl, NH4NO3) и солях аминов ([CH3NH3]Cl) есть ионная связь, несмотря на полное отсутствие атомов металлов.", "Ионная связь может существовать только в соединениях, содержащих хотя бы один атом металла.", "Катионы NH4^{+} и R−NH3^{+} образуют ионную связь с анионами так же, как катионы щелочных металлов."], ["Металлическая связь существует только в простых веществах-металлах и их сплавах (бронза, латунь, сталь).", "В оксидах, гидроксидах и солях металлов (CuO, NaOH, FeCl3) присутствует металлическая связь.", "В соединениях металлов с неметаллами действует ионная (или ковалентная в CrO3/Mn2O7), а не металлическая связь."], ["В этилате натрия C2H5ONa и ацетате натрия CH3COONa одновременно есть ионная, ковалентная полярная и ковалентная неполярная связи.", "В формиате натрия HCOONa есть ионная, ковалентная полярная и ковалентная неполярная связи.", "В HCOONa только один атом углерода — ковалентной неполярной связи C−C там нет."], ["В нитрате аммония NH4NO3 НЕТ ковалентной неполярной связи, потому что два атома азота находятся в разных ионах и не связаны друг с другом.", "В нитрате аммония NH4NO3 есть ковалентная неполярная связь N−N, так как в формуле два атома азота.", "NH4^{+} и NO3^{−} — два отдельных иона; атомы N напрямую не соединены."], ["В пероксиде натрия Na2O2 и пирите FeS2 сочетаются ионная и ковалентная неполярная связи, а ковалентных полярных связей нет.", "В карбиде алюминия Al4C3, как и в карбиде кальция CaC2, есть ковалентная неполярная связь C−C.", "Al4C3 — метанид (содержит одиночные ионы C^{4−} и только ионную связь), а CaC2 — ацетиленид (ион C2^{2−} со связью C≡C)."]]}, {"id": "f_hbonds", "sk": "h_bond", "ref": "05.10", "n": 4, "lvl": 3, "t": "Водородные связи и межмолекулярные взаимодействия", "s": [["Между собственными молекулами этанола C2H5OH, муравьиной кислоты HCOOH и анилина C6H5NH2 образуются водородные связи.", "Между собственными молекулами диметилового эфира CH3−O−CH3, ацетона CH3COCH3 и триметиламина (CH3)3N образуются водородные связи.", "В эфирах, кетонах и третичных аминах нет прямых связей O−H или N−H."], ["В хлороводороде HCl, сероводороде H2S и фосфине PH3 межмолекулярных водородных связей нет.", "В HCl и H2S есть водородные связи, так как хлор и сера — сильные неметаллы.", "Водородные связи в школьной модели ЕГЭ образуются только с F, O и N (2-й период, малый радиус и высокая ЭО)."], ["Среди аминов межмолекулярные водородные связи образуют первичные (R−NH2) и вторичные (R2NH) амины, но НЕ третичные (R3N).", "Ни один амин не образует водородных связей, так как это органические вещества.", "Наличие хотя бы одной связи N−H в первичных и вторичных аминах обеспечивает водородные связи."], ["В белках водородные связи бывают внутримолекулярными — они стабилизируют α-спираль вторичной структуры.", "Водородная связь может быть только межмолекулярной и никогда не возникает внутри одной молекулы.", "Внутримолекулярные H-связи характерны для белков, ДНК и салициловой кислоты."], ["В ряду F2 → Cl2 → Br2 → I2 переход от газов к жидкости и твёрдым кристаллам объясняется ростом сил Ван-дер-Ваальса при увеличении молярной массы.", "Иод I2 твёрдый при комнатной температуре из-за образования атомной кристаллической решётки.", "У I2 молекулярная решётка (кристаллы легко возгоняются), а твёрдое состояние связано с ростом дисперсионных сил Ван-дер-Ваальса."]]}, {"id": "f_lattices_props", "sk": "lattices", "ref": "06.9", "n": 4, "lvl": 3, "t": "Кристаллические решётки, аллотропы и физические свойства", "s": [["Немолекулярное строение объединяет три типа кристаллических решёток: атомную, ионную и металлическую.", "Веществами немолекулярного строения называют только ионные соединения.", "Алмаз, кварц SiO2 (атомная) и железо Fe (металлическая) — тоже вещества немолекулярного строения."], ["Белый фосфор (P4) и фуллерен (C60) имеют молекулярную кристаллическую решётку, а красный фосфор, алмаз и графит — атомную.", "Все аллотропные модификации углерода и фосфора имеют атомную кристаллическую решётку.", "Белый фосфор состоит из молекул P4, а фуллерен — из молекул C60, поэтому у них молекулярная решётка."], ["Оксид алюминия Al2O3 в ЕГЭ относят к ионной кристаллической решётке, а оксид кремния(IV) SiO2 — к атомной.", "Поскольку Al2O3 и SiO2 оба тугоплавки и нерастворимы в воде, оба имеют атомную решётку.", "Al2O3 — амфотерный оксид металла, и по канону ФИПИ его относят к ионной решётке."], ["Твёрдые ионные соли (например, NaCl) электрический ток НЕ проводят, а их расплавы и водные растворы — проводят.", "Любые ионные соли хорошо проводят электрический ток в твёрдом кристаллическом состоянии.", "В твёрдом кристалле ионы жёстко зафиксированы в узлах и не могут переносить заряд."], ["Силан SiH4 и тетрахлорид кремния SiCl4 имеют молекулярную кристаллическую решётку, а не атомную.", "Все соединения кремния в твёрдом состоянии имеют атомную кристаллическую решётку.", "Атомная решётка у Si, SiO2, SiC, Si3N4; летучие SiH4, SiF4, SiCl4 имеют молекулярную решётку."]]}], "calc": [{"id": "c_sigma_alkane", "sk": "cov_props", "ref": "03.5", "n": 4, "lvl": 2, "v": {"n": [1, 2, 3, 4, 5, 6]}, "q": "Сколько ВСЕГО σ-связей содержится в одной молекуле алкана состава C{=n}H{=2*n+2} (учитывая и C−C, и C−H связи)?", "a": "3 * n + 1", "dp": 0, "unit": "σ-связей", "ex": "В алкане C{=n}H{=2*n+2} все связи одинарные (каждая — 1 σ): связей C−C ровно ({=n} − 1) = {=n-1}, связей C−H ровно {=2*n+2}. Итого: {=n-1} + {=2*n+2} = {=3*n+1} σ-связей."}, {"id": "c_pi_count", "sk": "cov_props", "ref": "03.5", "n": 4, "lvl": 2, "v": {"_": [{"d": 1, "t": 0}, {"d": 2, "t": 0}, {"d": 0, "t": 1}, {"d": 1, "t": 1}, {"d": 2, "t": 1}, {"d": 0, "t": 2}, {"d": 3, "t": 0}]}, "q": "В структурной формуле молекулы содержится {=d} двойных и {=t} тройных связей (остальные — одинарные). Сколько ВСЕГО π-связей в этой молекуле?", "a": "d + 2 * t", "dp": 0, "unit": "π-связей", "ex": "Каждая двойная связь даёт 1 π-связь, каждая тройная — 2 π-связи, одинарные — 0. Итого: {=d} · 1 + {=t} · 2 = {=d+2*t} π-связей."}], "tasks": [{"id": "t01_demo2027", "type": "multi", "sk": "double_filter", "ref": "08.5", "n": 4, "lvl": 3, "q": "[ДЕМО-2027 ФИПИ] Из предложенного перечня выберите два вещества с ковалентной полярной химической связью, которые имеют ионную кристаллическую решётку.", "o": ["хлорид кальция", "оксид фосфора(V)", "этилат натрия", "аммиак", "гидроксид калия"], "a": [2, 4], "ex": "Проверяем оба фильтра: 1) CaCl2 — ионная решётка, но только ионная связь (нет ковалентной); 2) P2O5 — ковалентная полярная связь, но молекулярная решётка; 3) C2H5ONa — ионная решётка + полярные связи C−H, C−O (и C−C) → ДА; 4) NH3 — молекулярная решётка; 5) KOH — ионная решётка + полярная связь O−H → ДА. Ответ: 35."}, {"id": "t02_da_ionic", "type": "multi", "sk": "cov_mech", "ref": "02.17", "n": 4, "lvl": 3, "q": "Из предложенного перечня выберите два вещества ионного строения, в которых присутствует ковалентная связь, образованная по донорно-акцепторному механизму.", "o": ["аммиак", "угарный газ", "хлорид аммония", "хлорид метиламмония", "карбонат натрия"], "a": [2, 3], "ex": "1) NH3 — молекулярное строение и нет Д-А; 2) CO — есть Д-А, но молекулярное строение; 3) NH4Cl — ионная решётка + Д-А в NH4^{+} → ДА; 4) [CH3NH3]Cl — ионная решётка + Д-А в катионе метиламмония → ДА; 5) Na2CO3 — ионная, но Д-А нет. Ответ: 34."}, {"id": "t03_da_molec", "type": "multi", "sk": "cov_mech", "ref": "02.14", "n": 4, "lvl": 3, "q": "Выберите два вещества МОЛЕКУЛЯРНОГО строения, в которых имеется ковалентная связь, образованная по донорно-акцепторному механизму.", "o": ["озон", "нитрат калия", "оксид углерода(II)", "вода", "оксид углерода(IV)"], "a": [0, 2], "ex": "1) O3 — молекулярная решётка + Д-А связь → ДА; 2) KNO3 — есть Д-А в NO3^{−}, но ионная решётка (немолекулярное!); 3) CO — молекулярная решётка + Д-А (O → C) → ДА; 4) H2O и 5) CO2 — нет Д-А. Ответ: 13."}, {"id": "t04_nonpol_nonmol", "type": "multi", "sk": "ion_met", "ref": "04.7", "n": 4, "lvl": 3, "q": "Выберите два вещества НЕМОЛЕКУЛЯРНОГО строения, в которых присутствует ковалентная неполярная связь.", "o": ["пероксид водорода", "пероксид натрия", "кварц", "карбид кальция", "белый фосфор"], "a": [1, 3], "ex": "1) H2O2 — молекулярное строение; 2) Na2O2 — ионная решётка (немолекулярное) + связь O−O → ДА; 3) SiO2 — атомная (немолекулярное), но только полярные связи Si−O; 4) CaC2 — ионная решётка + связь C≡C → ДА; 5) P4 — молекулярная решётка. Ответ: 24."}, {"id": "t05_nonpol_org", "type": "multi", "sk": "cov_mech", "ref": "02.7", "n": 4, "lvl": 3, "q": "Выберите два органических вещества, в молекулах которых НЕТ ковалентной неполярной связи.", "o": ["этан", "диметиловый эфир", "этанол", "муравьиная кислота", "уксусная кислота"], "a": [1, 3], "ex": "Связи C−C есть в этане (CH3−CH3), этаноле (CH3−CH2−OH) и уксусной кислоте (CH3−COOH). В диметиловом эфире (CH3−O−CH3) атомы C разделены кислородом, а в муравьиной кислоте (HCOOH) только 1 атом C — неполярной связи нет. Ответ: 24."}, {"id": "t06_hbonds_org", "type": "multi", "sk": "h_bond", "ref": "05.12", "n": 4, "lvl": 3, "q": "Выберите два вещества, между молекулами которых (в чистом виде) образуются водородные связи.", "o": ["диметиловый эфир", "муравьиная кислота", "триметиламин", "анилин", "сероводород"], "a": [1, 3], "ex": "Ищем прямые связи H−F, H−O или H−N: 1) CH3−O−CH3 — нет O−H; 2) HCOOH — есть O−H → ДА; 3) (CH3)3N — третичный амин, нет N−H; 4) C6H5NH2 — первичный амин, есть N−H → ДА; 5) H2S — сера не входит в F, O, N. Ответ: 24."}, {"id": "t07_hbonds_inorg", "type": "multi", "sk": "h_bond", "ref": "05.8", "n": 4, "lvl": 2, "q": "Выберите два неорганических вещества, между молекулами которых образуются водородные связи.", "o": ["хлороводород", "фтороводород", "фосфин", "пероксид водорода", "силан"], "a": [1, 3], "ex": "1) HCl — Cl не образует H-связи; 2) HF — есть H−F → ДА; 3) PH3 — P не входит в F, O, N; 4) H2O2 — есть связи O−H → ДА; 5) SiH4 — Si не входит в F, O, N. Ответ: 24."}, {"id": "t08_atomic_allotropes", "type": "multi", "sk": "lattices", "ref": "06.10", "n": 4, "lvl": 3, "q": "Выберите два вещества с АТОМНОЙ кристаллической решёткой.", "o": ["оксид углерода(IV)", "карборунд", "белый фосфор", "красный фосфор", "оксид алюминия"], "a": [1, 3], "ex": "1) CO2 — молекулярная; 2) карборунд SiC — атомная → ДА; 3) белый фосфор P4 — молекулярная; 4) красный фосфор — полимерная атомная → ДА; 5) Al2O3 — в ЕГЭ ионная. Ответ: 24."}, {"id": "t09_nonmol_all", "type": "multi", "sk": "lattices", "ref": "06.11", "n": 4, "lvl": 2, "q": "Выберите два вещества НЕМОЛЕКУЛЯРНОГО строения.", "o": ["белый фосфор", "кремнезём", "хлорид аммония", "глюкоза", "иод"], "a": [1, 2], "ex": "Немолекулярное строение = атомная, ионная или металлическая решётка. Кремнезём SiO2 (атомная) и хлорид аммония NH4Cl (ионная) — немолекулярного строения. P4, C6H12O6 и I2 — молекулярные. Ответ: 23."}, {"id": "t10_molec_polar", "type": "multi", "sk": "lattices", "ref": "06.7", "n": 4, "lvl": 2, "q": "Выберите два вещества МОЛЕКУЛЯРНОГО строения с ковалентными полярными связями.", "o": ["силан", "кварц", "сульфат аммония", "сернистый газ", "фуллерен"], "a": [0, 3], "ex": "1) SiH4 — молекулярная решётка + полярные связи Si−H → ДА; 2) SiO2 — атомная (немолекулярная); 3) (NH4)2SO4 — ионная (немолекулярная); 4) SO2 — молекулярная + полярные связи S=O → ДА; 5) C60 — молекулярная, но только неполярные связи C−C. Ответ: 14."}, {"id": "t11_nonpolar_mol", "type": "multi", "sk": "cov_props", "ref": "03.13", "n": 4, "lvl": 3, "q": "Выберите два вещества с ковалентными полярными связями, молекулы которых в целом НЕПОЛЯРНЫ.", "o": ["аммиак", "сероводород", "метан", "углекислый газ", "хлорметан"], "a": [2, 3], "ex": "1) NH3 — пирамида (полярная); 2) H2S — уголковая (полярная); 3) CH4 — правильный тетраэдр (неполярная) → ДА; 4) CO2 — линейная 180° (неполярная) → ДА; 5) CH3Cl — несимметричный тетраэдр (полярная). Ответ: 34."}, {"id": "t12_nonpolar_mol_traps", "type": "multi", "sk": "cov_props", "ref": "03.14", "n": 4, "lvl": 3, "q": "Выберите два вещества, молекулы которых в целом НЕПОЛЯРНЫ, несмотря на наличие ковалентных полярных связей.", "o": ["SO2", "SO3", "BF3", "PH3", "H2O"], "a": [1, 2], "ex": "SO3 и BF3 имеют форму плоского симметричного треугольника (у центрального атома нет неподелённой пары) — диполи компенсируются. SO2 и H2O — уголковые, PH3 — пирамида (все три полярны). Ответ: 23."}, {"id": "t13_only_polar_pi", "type": "multi", "sk": "cov_props", "ref": "08.5", "n": 4, "lvl": 3, "q": "Выберите два вещества, в которых присутствуют ТОЛЬКО ковалентные полярные связи и при этом есть π-связь.", "o": ["формальдегид", "карбид кальция", "сернистый газ", "диметиловый эфир", "ацетилен"], "a": [0, 2], "ex": "1) HCHO (H2C=O) — только полярные (нет C−C) + двойная C=O (1 π) → ДА; 2) CaC2 — есть ионная и неполярная C≡C; 3) SO2 — только полярные S=O + есть π-связи → ДА; 4) CH3−O−CH3 — нет π-связей; 5) C2H2 — есть неполярная связь C≡C. Ответ: 13."}, {"id": "t14_ionic_only", "type": "multi", "sk": "ion_met", "ref": "04.7", "n": 4, "lvl": 2, "q": "Выберите два вещества, в которых присутствует ТОЛЬКО ионная химическая связь.", "o": ["карбид алюминия", "карбид кальция", "гидрид натрия", "гидроксид натрия", "пероксид бария"], "a": [0, 2], "ex": "1) Al4C3 — метанид (ионы Al^{3+} и C^{4−}, только ионная) → ДА; 2) CaC2 — есть C≡C; 3) NaH — Na^{+} и H^{−}, только ионная → ДА; 4) NaOH — есть полярная O−H; 5) BaO2 — есть неполярная O−O. Ответ: 13."}, {"id": "t15_ionic_and_nonpol", "type": "multi", "sk": "ion_met", "ref": "04.7", "n": 4, "lvl": 3, "q": "Выберите два вещества, в которых одновременно присутствуют ионная и ковалентная неполярная связи.", "o": ["формиат натрия", "ацетат натрия", "пирит", "хлорид аммония", "оксид алюминия"], "a": [1, 2], "ex": "1) HCOONa — только 1 атом C, неполярной связи нет; 2) CH3COONa — ионная + полярные + неполярная C−C → ДА; 3) FeS2 — ионная + неполярная S−S → ДА; 4) NH4Cl — нет неполярной; 5) Al2O3 — только ионная. Ответ: 23."}, {"id": "t16_phys_sublim", "type": "multi", "sk": "phys_props", "ref": "07.8", "n": 4, "lvl": 2, "q": "Выберите два вещества, которые в твёрдом состоянии имеют низкую температуру плавления, летучи и способны легко возгоняться при нагревании.", "o": ["оксид кремния(IV)", "иод", "хлорид натрия", "оксид углерода(IV)", "графит"], "a": [1, 3], "ex": "Низкая t_пл, летучесть и лёгкая возгонка — признаки молекулярной кристаллической решётки. В списке это I2 и CO2 (сухой лёд). SiO2 и графит — атомные, NaCl — ионная. Ответ: 24."}, {"id": "t17_phys_melt_cond", "type": "multi", "sk": "phys_props", "ref": "07.5", "n": 4, "lvl": 3, "q": "Выберите два вещества, которые НЕ проводят электрический ток в твёрдом состоянии, но хорошо проводят его в расплаве.", "o": ["медь", "нитрат калия", "алмаз", "хлорид бария", "сахароза"], "a": [1, 3], "ex": "Ток не идёт в твёрдом виде, но идёт в расплаве — признак ионной кристаллической решётки. Это KNO3 и BaCl2. Медь проводит и в твёрдом виде; алмаз (атомная) и сахароза (молекулярная) не проводят в расплаве. Ответ: 24."}, {"id": "t18_metallic_trap", "type": "multi", "sk": "ion_met", "ref": "04.14", "n": 4, "lvl": 2, "q": "Выберите два вещества (или материала) с МЕТАЛЛИЧЕСКОЙ химической связью.", "o": ["оксид меди(II)", "латунь", "хлорид железа(III)", "алюминий", "графит"], "a": [1, 3], "ex": "Металлическая связь действует только в простых веществах-металлах (Al) и сплавах (латунь — сплав Cu и Zn). В CuO и FeCl3 связь ионная; графит — неметалл с атомной решёткой (хоть и проводит ток!). Ответ: 24."}, {"id": "t19_trivial_da_ionic", "type": "multi", "sk": "double_filter", "ref": "08.7", "n": 4, "lvl": 3, "q": "Выберите два вещества с ИОННОЙ кристаллической решёткой, в которых присутствует ковалентная связь, образованная по донорно-акцепторному механизму.", "o": ["нашатырь", "нашатырный спирт", "жёлтая кровяная соль", "корунд", "поташ"], "a": [0, 2], "ex": "1) Нашатырь NH4Cl — ионная решётка + Д-А в NH4^{+} → ДА; 2) нашатырный спирт (водный NH3) — молекулярный, без Д-А; 3) жёлтая кровяная соль K4[Fe(CN)6] — ионная решётка + Д-А в комплексном ионе → ДА; 4) корунд Al2O3 — только ионная; 5) поташ K2CO3 — нет Д-А. Ответ: 13."}, {"id": "t20_only_cov_trap", "type": "multi", "sk": "double_filter", "ref": "08.8", "n": 4, "lvl": 3, "q": "Выберите два вещества, в которых присутствуют ТОЛЬКО ковалентные химические связи.", "o": ["нитрат аммония", "азотная кислота", "оксид марганца(VII)", "гидроксид калия", "фенолят натрия"], "a": [1, 2], "ex": "1) NH4NO3 — есть ионная связь; 2) HNO3 — кислота, только ковалентные полярные связи → ДА; 3) Mn2O7 — кислотный оксид металла в высшей с.о. (+7), в ЕГЭ только ковалентные полярные связи → ДА; 4) KOH и 5) C6H5ONa — есть ионная связь. Ответ: 23."}, {"id": "t21_match_lattice", "type": "match", "sk": "lattices", "ref": "06.7", "n": 4, "lvl": 3, "q": "Установите соответствие между веществом и типом его кристаллической решётки (в твёрдом состоянии по канону ЕГЭ).", "left": ["Кварц (SiO2)", "Корунд (Al2O3)", "Белый фосфор (P4)", "Бронза"], "right": ["Атомная", "Ионная", "Молекулярная", "Металлическая"], "a": [0, 1, 2, 3], "ex": "SiO2 — атомная; Al2O3 — ионная (в ЕГЭ); белый фосфор P4 — молекулярная; бронза (сплав) — металлическая."}, {"id": "t22_match_bonds", "type": "match", "sk": "ion_met", "ref": "04.7", "n": 4, "lvl": 3, "q": "Установите соответствие между формулой вещества и полным набором видов химической связи в нём.", "left": ["CaCl2", "NH4Cl", "Na2O2", "C2H5ONa"], "right": ["Только ионная", "Ионная и ковалентная полярная", "Ионная и ковалентная неполярная", "Ионная, ковалентная полярная и ковалентная неполярная"], "a": [0, 1, 2, 3], "ex": "CaCl2 — только ионная; NH4Cl — ионная + полярная (N−H); Na2O2 — ионная + неполярная (O−O); C2H5ONa — ионная + полярные (C−H, C−O) + неполярная (C−C)."}, {"id": "t23_num_pi_n2_co", "type": "num", "sk": "cov_props", "ref": "03.5", "n": 4, "lvl": 2, "q": "Сколько π-связей содержится в одной молекуле угарного газа CO (C≡O)? Введите целое число.", "a": 2, "ex": "В молекуле CO между углеродом и кислородом тройная связь (2 обменные + 1 донорно-акцепторная). Любая тройная связь состоит из 1 σ-связи и 2 π-связей."}, {"id": "t24_one_graphite", "type": "one", "sk": "phys_props", "ref": "07.5", "n": 4, "lvl": 3, "q": "Какое вещество имеет АТОМНУЮ кристаллическую решётку, но при этом мягкое и проводит электрический ток в твёрдом состоянии?", "o": ["Графит", "Алмаз", "Кварц", "Иод"], "a": 0, "ex": "Графит построен из плоских атомных слоёв (sp²): слабые силы между слоями делают его мягким, а делокализованные π-электроны в слоях обеспечивают электропроводность.", "d": {"1": "Алмаз сверхтвёрдый и является диэлектриком.", "2": "Кварц SiO2 очень твёрдый и ток не проводит.", "3": "У иода I2 молекулярная, а не атомная решётка, и он не проводит ток."}}], "subjectSlug": "chemistry", "_kim": {"4": {"b": 1, "l": "Б"}}, "_kon": {"01": {"t": "Модуль 01. Зачем атомы соединяются: электроотрицательность и карта связей", "x": "Атомы образуют [[химическая связь|химическую связь]], чтобы снизить свою энергию и получить устойчивую завершённую электронную оболочку. То, *как именно* они делят электроны, зависит от разницы их [[электроотрицательность|электроотрицательности]] — способности перетягивать к себе общую электронную пару."}, "01.1": {"t": "Модуль 01 · Главная мысль.", "x": "Атомы образуют [[химическая связь|химическую связь]], чтобы снизить свою энергию и получить устойчивую завершённую электронную оболочку. То, *как именно* они делят электроны, зависит от разницы их [[электроотрицательность|электроотрицательности]] — способности перетягивать к себе общую электронную пару."}, "01.13": {"t": "Модуль 01 · Граница школьной модели и реальности (на 95–100 баллов)", "x": "В школьной модели ЕГЭ действует чёткое правило: **металл + неметалл** (в солях, основаниях, основных и амфотерных оксидах) — это **ионная связь**, а **неметалл + неметалл** — **ковалентная**. Но у этого правила есть два важнейших экзаменационных дополнения:\n1. В **солях аммония** (NH4Cl, NH4NO3) и **солях аминов** ([CH3NH3]Cl) нет ни одного атома металла, но между катионом и анионом всё равно **ионная связь**!\n2. В **кислотных оксидах металлов** в высоких степенях окисления (CrO3, Mn2O7) связь **ковалентная полярная**, а не ионная. Граничные хлориды BeCl2 и AlCl3 в реальности также имеют сильную долю ковалентности, поэтому в корректных заданиях ФИПИ их не ставят в спорные пары с классическими ионными солями."}, "02": {"t": "Модуль 02. Ковалентная связь: обменный и донорно-акцепторный механизмы", "x": "[[Ковалентная связь]] образуется за счёт общей электронной пары. Она может возникнуть двумя способами: **обменным** (каждый атом даёт по одному неспаренному электрону) и **[[донорно-акцепторный механизм|донорно-акцепторным]]** (один атом отдаёт готовую пару, а другой предоставляет пустую орбиталь). После образования связи обоих типов становятся полностью неразличимы."}, "02.1": {"t": "Модуль 02 · Главная мысль.", "x": "[[Ковалентная связь]] образуется за счёт общей электронной пары. Она может возникнуть двумя способами: **обменным** (каждый атом даёт по одному неспаренному электрону) и **[[донорно-акцепторный механизм|донорно-акцепторным]]** (один атом отдаёт готовую пару, а другой предоставляет пустую орбиталь). После образования связи обоих типов становятся полностью неразличимы."}, "02.6": {"t": "Модуль 02 · 2. Ловушка № 1: ковалентная неполярная связь в сложных веществах", "x": "• ****Пероксиды**** — Скрытая неполярная связь: Кислородный мостик −O−O−; Примеры из заданий ЕГЭ: H2O2, Na2O2, K2O2, BaO2\n• ****Пирит (дисульфид железа)**** — Скрытая неполярная связь: Связь −S−S− в дисульфид-ионе S2^{2−}; Примеры из заданий ЕГЭ: FeS2\n• ****Ацетилениды (карбид кальция)**** — Скрытая неполярная связь: Тройная связь C≡C в ионе C2^{2−}; Примеры из заданий ЕГЭ: CaC2, Na2C2 (но в Al4C3 связи C−C нет!)\n• ****Гидразин и дисилан**** — Скрытая неполярная связь: Связи N−N и Si−Si; Примеры из заданий ЕГЭ: N2H4, Si2H6\n• ****Органика с цепью из ≥ 2 атомов C**** — Скрытая неполярная связь: Связи C−C, C=C, C≡C или ароматическая связь в бензольном кольце; Примеры из заданий ЕГЭ: C2H6, C2H4, C2H2, C6H6, C2H5OH, C2H5ONa, CH3COOH, CH3COONa, глюкоза"}, "02.7": {"t": "Модуль 02 · Анти-паттерн: органические вещества БЕЗ ковалентной неполярной связи", "x": "Не попадайся на обратную ловушку в органике! Далеко не в каждом органическом веществе есть связь C−C. Ковалентной неполярной связи **НЕТ**:\n- в веществах с **одним атомом углерода**: метан CH4, метанол CH3OH, формальдегид HCHO, муравьиная кислота HCOOH, формиат натрия HCOONa, метиламин CH3NH2, хлорметан CH3Cl, мочевина (NH2)2CO;\n- в веществах, где атомы углерода **разделены кислородом или азотом**: диметиловый эфир CH3−O−CH3, метилформиат HCOO−CH3, диметиламин CH3−NH−CH3, триметиламин (CH3)3N."}, "02.14": {"t": "Модуль 02 · 4. Полный список ЕГЭ для донорно-акцепторного механизма", "x": "• ****Соли аммония** (NH4Cl, NH4NO3, (NH4)2SO4, CH3COONH4)** — Кто донор → кто акцептор: N (из NH3) → H^{+}; На что смотреть в перечне КИМ: Любое слово «аммония» или формула с NH4\n• ****Соли аминов и аминокислот с кислотами** ([CH3NH3]Cl, [C6H5NH3]Br, [H3NCH2COOH]Cl)** — Кто донор → кто акцептор: N (аминогруппы) → H^{+}; На что смотреть в перечне КИМ: Хлориды, сульфаты, бромиды метиламмония, фениламмония, глициния\n• ****Ион гидроксония** (H3O^{+})** — Кто донор → кто акцептор: O (из H2O) → H^{+}; На что смотреть в перечне КИМ: Встречается в формулах кислых растворов\n• ****Угарный газ** (CO)** — Кто донор → кто акцептор: O → пустая 2p-орбиталь C; На что смотреть в перечне КИМ: Оксид углерода(II), угарный газ\n• ****Озон** (O3)** — Кто донор → кто акцептор: Центральный атом O → крайний атом O; На что смотреть в перечне КИМ: Озон O3 (а в кислороде O2 её нет!)…"}, "02.15": {"t": "Модуль 02 · Анти-паттерн: в NH3 и H2O донорно-акцепторной связи ещё нет!", "x": "Самая частая ошибка в этом блоке — выбирать **аммиак NH3** или **воду H2O**! В молекулах NH3 и H2O **НЕТ** донорно-акцепторных связей: все связи там образованы по обменному механизму. Аммиак и вода лишь *способны быть донорами*, когда присоединяют H^{+} (образуя NH4^{+} и H3O^{+}) или входят в состав комплексного иона."}, "02.17": {"t": "Модуль 02 · Мост к КИМ (№ 4 КИМ ЕГЭ-2027)", "x": "**Как спрашивают:** Выберите два вещества, в которых есть ковалентная связь, образованная по донорно-акцепторному механизму (часто в паре с требованием «имеют ионную кристаллическую решётку» или «молекулярное строение»).\n**На чём ловят:** Подлавливают на NH3 (нет Д-А!), CO2 (нет Д-А, есть только в CO!), O2 (нет Д-А, есть только в O3!) и на органических солях аминов вроде хлорида метиламмония ([CH3NH3]Cl — есть Д-А и ионная решётка!).\n**Как читать:** Если просят **Д-А + молекулярное строение** — ищи CO, O3, HNO3, C6H5NO2. Если просят **Д-А + ионную решётку** — ищи соли аммония (NH4Cl, NH4NO3), соли аминов ([CH3NH3]Cl), нитраты (KNO3) и комплексные соли (Na[Al(OH)4])."}, "03": {"t": "Модуль 03. Характеристики ковалентной связи: σ- и π-связи, длина, энергия и полярность молекул", "x": "Прочность и реакционная способность вещества зависят от характеристик ковалентной связи: **кратности**, **длины** и **энергии**. Чем больше кратность связи и меньше радиусы атомов, тем связь **короче** и **прочнее** (выше энергия). А полярность всей молекулы определяется не только полярностью отдельных связей, но и её **геометрической симметрией**."}, "03.1": {"t": "Модуль 03 · Главная мысль.", "x": "Прочность и реакционная способность вещества зависят от характеристик ковалентной связи: **кратности**, **длины** и **энергии**. Чем больше кратность связи и меньше радиусы атомов, тем связь **короче** и **прочнее** (выше энергия). А полярность всей молекулы определяется не только полярностью отдельных связей, но и её **геометрической симметрией**."}, "03.5": {"t": "Модуль 03 · 1. Кратность связи: σ- и π-связи", "x": "• ****Одинарная** (A−B)** — Состав (σ и π): 1 σ; Примеры: H2, Cl2, CH4, C−C в этане; Сравнение длины и прочности: Самая длинная, самая низкая энергия\n• ****Двойная** (A=B)** — Состав (σ и π): 1 σ + 1 π; Примеры: O2, CO2 (2 σ + 2 π), SO2, SO3, C=C в алкенах, C=O в альдегидах (HCHO, CH3CHO), кетонах (CH3COCH3), карбоновых кислотах (CH3COOH), сложных эфирах, CO3^{2−} и N=O в HNO3/NO3^{−}; Сравнение длины и прочности: Короче и прочнее одинарной\n• ****Тройная** (A≡B)** — Состав (σ и π): 1 σ + 2 π; Примеры: N2, CO, C≡C в алкинах и карбиде кальция CaC2, C≡N в цианидах; Сравнение длины и прочности: Самая короткая и самая прочная (N2 инертен при н.у.!)"}, "03.8": {"t": "Модуль 03 · 2. Длина и энергия связи: две главные зависимости", "x": "• **Фактор 1 — радиусы атомов (по таблице ФИПИ).** В группе сверху вниз радиус атома растёт, поэтому связь удлиняется и ослабевает. Например, в ряду галогеноводородов HF → HCl → HBr → HI радиус галогена растёт → длина связи **увеличивается** → энергия связи **уменьшается** (поэтому HI — самая сильная кислота в воде, она легче всего отдаёт H^{+}).\n• **Фактор 2 — кратность связи.** Чем больше общих пар стягивает два ядра, тем ближе они друг к другу. В ряду C−C (0,154 нм) → C=C (0,134 нм) → C≡C (0,120 нм) длина связи **уменьшается**, а общая энергия разрыва связи **растёт**.\n• **Степень полярности связи (по ΔЭО).** Чем дальше друг от друга элементы по шкале электроотрицательности в таблице ФИПИ, тем выше полярность связи: полярность растёт в рядах H−C < H−N < H−O < H−F (по периоду к фтору) и H−I < H−Br < H−Cl < H−F (по группе вверх к фтору)."}, "03.12": {"t": "Модуль 03 · 3. Полярность связи vs полярность всей молекулы", "x": "• **CO2, CS2, BeCl2 (газ), C2H2** — Тип связей: Ковалентные полярные (в C2H2 ещё C≡C); Геометрия: Линейная (180°, sp), симметричная; Полярность молекулы: **Неполярная**\n• **BF3, SO3, C2H4 (этилен), C6H6 (бензол)** — Тип связей: Ковалентные полярные (в C2H4, C6H6 ещё C–C); Геометрия: Плоская симметричная (120°, sp²); Полярность молекулы: **Неполярная**\n• **CH4, CCl4, SiH4 (силан), CF4, C2H6 (этан)** — Тип связей: Ковалентные полярные (в C2H6 ещё C−C); Геометрия: Правильный тетраэдр (109,5°, sp³), симметричная; Полярность молекулы: **Неполярная**\n• **H2O, H2S, SO2, O3** — Тип связей: Ковалентные (в O3 неполярные по ЭО, но с разным распределением заряда); Геометрия: Уголковая (из-за неподелённых пар); Полярность молекулы: **Полярная**\n• **NH3, PH3 (фосфин), PCl3** — Тип связей: Ковалентные полярные; Геометрия: Тригональная пирамида (есть неподелённая пара); Полярность молекулы: **Полярная**…"}, "03.13": {"t": "Модуль 03 · 3. Полярность связи vs полярность всей молекулы", "x": "**Шаг 1.** **Сравниваем CO2 и H2O.** В обеих молекулах связи ковалентные полярные (C=O и O−H). У углерода в CO2 нет неподелённых пар — молекула линейна (180°), диполи компенсируются → **неполярная молекула**. У кислорода в H2O две неподелённые пары — молекула уголковая (104,5°), диполи складываются → **полярная молекула**.\n**Шаг 2.** **Сравниваем длину и прочность связей в HF, HCl, HBr, HI и в C2H6, C2H4, C2H2.** В ряду галогеноводородов радиус галогена растёт от F к I, поэтому самая короткая и прочная связь — H−F, а самая длинная и слабая — H−I. В ряду этан → этилен → ацетилен кратность углерод-углеродной связи растёт (1 → 2 → 3), поэтому длина связи C−C > C=C > C≡C, а энергия связи растёт в обратном порядке: C−C < C=C < C≡C."}, "03.14": {"t": "Модуль 03 · Ловушка ЕГЭ: пары SO2 / SO3 и NH3 / BF3", "x": "Не путай две похожие молекулы с одинаковым числом атомов: **SO2 и SO3**, а также **NH3 и BF3**!\n- В SO3 (степень окисления серы +6) у серы не осталось неподелённых пар → плоский симметричный треугольник → молекула **неполярна**. В SO2 (S^{+4}) осталась одна неподелённая пара → молекула изогнута (уголковая) → **полярна**.\n- В BF3 у бора нет неподелённой пары → симметричный треугольник → **неполярна**. В NH3 у азота есть неподелённая пара → пирамида → **полярна**."}, "04": {"t": "Модуль 04. Ионная и металлическая связь: от электростатики до «электронного газа»", "x": "**[[Ионная связь]]** — это электростатическое притяжение противоположно заряженных ионов (катионов и анионов). **[[Металлическая связь]]** — это притяжение положительных ионов-атомов металла к обобществлённому «морю» свободных электронов. Обе связи, в отличие от ковалентной, действуют во все стороны вокруг каждой частицы."}, "04.1": {"t": "Модуль 04 · Главная мысль.", "x": "**[[Ионная связь]]** — это электростатическое притяжение противоположно заряженных ионов (катионов и анионов). **[[Металлическая связь]]** — это притяжение положительных ионов-атомов металла к обобществлённому «морю» свободных электронов. Обе связи, в отличие от ковалентной, действуют во все стороны вокруг каждой частицы."}, "04.3": {"t": "Модуль 04 · 1. Как образуется ионная связь", "x": "Na − e⁻ → Na^{+}\nCl + e⁻ → Cl^{−}"}, "04.7": {"t": "Модуль 04 · 2. Смешанные связи: главный сюжет задания № 4", "x": "• ****Только ионная**** — Где какая связь: Металл + одноатомный неметалл; Типовые примеры ЕГЭ: NaCl, CaCl2, MgO, Al2O3, Na2S, Li3N, NaH, Al4C3\n• ****Ионная + ковалентная полярная**** — Где какая связь: Ионная между катионом и анионом; ковалентная полярная внутри сложного иона (OH^{−}, SO4^{2−}, NO3^{−}, HCO3^{−}, NH4^{+}); Типовые примеры ЕГЭ: KOH, NaOH, Na2SO4, KNO3, CaCO3, кислые соли (NaHCO3, KHSO4), NH4Cl, NH4NO3, HCOONa, CH3ONa, [CH3NH3]Cl (а в кристаллогидратах вроде CuSO4·5H2O добавляются ещё и водородные связи!)\n• ****Ионная + ковалентная неполярная**** — Где какая связь: Ионная между металлом и двухъядерным анионом (O2^{2−}, C2^{2−}, S2^{2−}); неполярная внутри аниона; Типовые примеры ЕГЭ: Na2O2, BaO2, K2O2, CaC2, FeS2…"}, "04.8": {"t": "Модуль 04 · Анти-паттерн: ионная связь БЕЗ атомов металла", "x": "Самый коварный анти-паттерн № 4 — **соли аммония** (NH4Cl, (NH4)2SO4, NH4NO3, CH3COONH4) и **соли аминов** ([CH3NH3]Cl, [C6H5NH3]Cl). Ученики видят только неметаллы (N, H, Cl) и решают, что ионной связи тут нет. Это ошибка! Катион NH4^{+} ведёт себя точно так же, как катион щелочного металла (Na^{+} или K^{+}). Поэтому в любой соли аммония и любой соли амина **есть ионная связь** (между катионом и анионом), **ковалентная полярная** (внутри NH4^{+}) и **донорно-акцепторный механизм**!"}, "04.14": {"t": "Модуль 04 · Ловушка ЕГЭ: не ищи металлическую связь в соединениях металлов!", "x": "Где есть металлическая связь? **Только в простых веществах-металлах** (Na, K, Mg, Al, Fe, Cu, Ag, Au, Hg…) и **в сплавах** (латунь, бронза, сталь, чугун). В солях, оксидах и гидроксидах металлов (FeCl3, CuO, NaOH) металлической связи **НЕТ** — там ионная связь!"}, "05": {"t": "Модуль 05. Водородная связь и межмолекулярные взаимодействия", "x": "Молекулы притягиваются друг к другу слабыми [[межмолекулярные взаимодействия|силами Ван-дер-Ваальса]]. Но если в молекуле атом водорода H ковалентно связан с сильно электроотрицательным атомом **F, O или N**, между молекулами возникает дополнительная и гораздо более прочная **[[водородная связь]]** — она резко повышает температуру кипения и растворимость в воде."}, "05.1": {"t": "Модуль 05 · Главная мысль.", "x": "Молекулы притягиваются друг к другу слабыми [[межмолекулярные взаимодействия|силами Ван-дер-Ваальса]]. Но если в молекуле атом водорода H ковалентно связан с сильно электроотрицательным атомом **F, O или N**, между молекулами возникает дополнительная и гораздо более прочная **[[водородная связь]]** — она резко повышает температуру кипения и растворимость в воде."}, "05.8": {"t": "Модуль 05 · 3. Где есть водородная связь: точный список ЕГЭ", "x": "• ****Неорганические водородные соединения**** — Нужная группа в молекуле: H−F, H−O, H−N; Примеры ЕГЭ: HF, H2O, H2O2, NH3, N2H4 (гидразин)\n• ****Кислородсодержащие кислоты**** — Нужная группа в молекуле: Гидроксогруппа −O−H; Примеры ЕГЭ: H2SO4, HNO3, H3PO4, HClO4\n• ****Спирты и фенолы**** — Нужная группа в молекуле: Гидроксильная группа −OH; Примеры ЕГЭ: CH3OH, C2H5OH, этиленгликоль (HO−CH2−CH2−OH), глицерин (CH2(OH)−CH(OH)−CH2(OH)), фенол (C6H5OH)\n• ****Карбоновые кислоты**** — Нужная группа в молекуле: Карбоксильная группа −COOH; Примеры ЕГЭ: HCOOH, CH3COOH, бензойная кислота (образуют прочные димеры!)\n• ****Первичные и вторичные амины, аминокислоты**** — Нужная группа в молекуле: Группы −NH2, −NH− (и −COOH); Примеры ЕГЭ: CH3NH2, (CH3)2NH, анилин C6H5NH2, глицин, аланин…"}, "05.10": {"t": "Модуль 05 · Анти-паттерн: где водородной связи между своими молекулами НЕТ!", "x": "Абсолютный рекордсмен по ловушкам в этом разделе — вещества, где **есть и кислород/азот, и водород, но они НЕ связаны друг с другом**! Между собственными молекулами водородной связи **НЕТ**:\n- в **простых эфирах** (CH3−O−CH3 — водород связан только с C, а не с O! Поэтому диметиловый эфир — газ с t_кип = −24 °C, а его изомер этанол C2H5−OH — жидкость с t_кип = +78 °C);\n- в **альдегидах** (HCHO, CH3CHO), **кетонах** (CH3COCH3) и **сложных эфирах** (CH3COOCH3);\n- в **третичных аминах** ((CH3)3N — у азота не осталось ни одного атома H!);\n- в **HCl, HBr, HI, H2S, фосфине PH3, силане SiH4 и всех углеводородах** (CH4, C2H6, C6H6) — у Cl, S, P, Si, C либо слишком большой радиус, либо недостаточная электроотрицательность."}, "05.12": {"t": "Модуль 05 · 3. Где есть водородная связь: точный список ЕГЭ", "x": "**Задача:** в каких веществах из списка этанол, диметиловый эфир, метиламин, триметиламин, сероводород между молекулами образуются водородные связи?\n**Шаг 1. Этанол (CH3−CH2−OH).** Есть связь O−H → водородные связи **ЕСТЬ**.\n**Шаг 2. Диметиловый эфир (CH3−O−CH3).** Все атомы H прицеплены к углероду, связи O−H нет → водородных связей между его молекулами **НЕТ**.\n**Шаг 3. Метиламин (CH3−NH2).** Первичный амин, есть две связи N−H → водородные связи **ЕСТЬ**.\n**Шаг 4. Триметиламин ((CH3)3N).** Третичный амин, при азоте нет атомов H → водородных связей между его молекулами **НЕТ**.\n**Шаг 5. Сероводород (H2S).** Сера стоит в 3-м периоде и не входит в тройку F, O, N → водородных связей **НЕТ**. Итог: **этанол** и **метиламин**."}, "06": {"t": "Модуль 06. Молекулярное и немолекулярное строение: четыре типа кристаллических решёток", "x": "Все твёрдые вещества делятся на вещества **молекулярного строения** (состоят из отдельных молекул — только **молекулярная решётка**) и **немолекулярного строения** (непрерывный каркас из частиц — **атомная**, **ионная** или **металлическая решётка**). Тип решётки определяет, какие частицы стоят в узлах кристалла и какие связи их держат."}, "06.1": {"t": "Модуль 06 · Главная мысль.", "x": "Все твёрдые вещества делятся на вещества **молекулярного строения** (состоят из отдельных молекул — только **молекулярная решётка**) и **немолекулярного строения** (непрерывный каркас из частиц — **атомная**, **ионная** или **металлическая решётка**). Тип решётки определяет, какие частицы стоят в узлах кристалла и какие связи их держат."}, "06.7": {"t": "Модуль 06 · 3. Строгие списки веществ для каждого типа решётки на ЕГЭ", "x": "• ****Атомная** (немолекулярная)** — Кто сюда входит (строгий канон ЕГЭ-2027): **Простые вещества:** C (алмаз, графит), Si (кремний), B (бор), Ge (германий), **P (красный и чёрный фосфор)**.\n**Сложные вещества:** **SiO2** (кварц, кремнезём, песок), **SiC** (карборунд), **BN** (нитрид бора), Si3N4.\n• ****Молекулярная** (молекулярная)** — Кто сюда входит (строгий канон ЕГЭ-2027): **Все остальные ковалентные вещества** (в твёрдом состоянии!): простые неметаллы-молекулы (H2, O2, O3, N2, F2, Cl2, Br2, I2, S8, **белый фосфор P4**, **фуллерен C60**), благородные газы; **большинство кислотных оксидов неметаллов** (CO2, SO2, SO3, P2O5/P4O10, Cl2O7) и жидкий Mn2O7; несолеобразующие оксиды (CO, NO, N2O); все кислоты и водородные соединения неметаллов (H2O, H2O2, NH3, HCl, H2S, SiH4, PH3, H2SO4, HNO3, H3PO4); **почти вся несолевая органика** (углеводороды, спирты, фенолы, альдегиды, кетоны, карбоновые кислоты, эфиры, амины, углеводы…"}, "06.9": {"t": "Модуль 06 · Пять классических капканов ФИПИ по решёткам", "x": "Запомни пять главных ловушек по кристаллическим решёткам:\n1. **Белый фосфор (P4) vs Красный фосфор (P_красн.)**: белый фосфор состоит из молекул-тетраэдров P4 → **молекулярная** решётка (мягкий, летучий, плавится при +44 °C). Красный и чёрный фосфор имеют полимерное строение → **атомная** решётка.\n2. **Алмаз и графит vs Фуллерен (C60)**: алмаз и графит — **атомная** решётка; фуллерен C60 состоит из отдельных «футбольных мячей» по 60 атомов → **молекулярная** решётка.\n3. **Al2O3 (корунд) vs SiO2 (кварц)**: оба очень твёрдые и тугоплавкие, но Al2O3 — амфотерный оксид металла, и в рамках ЕГЭ его относят к **ионной** кристаллической решётке, а SiO2 — к **атомной**!\n4. **Не каждое соединение кремния имеет атомную решётку!** У Si, SiO2 и SiC решётка **атомная**, а у силана SiH4, SiF4 и SiCl4 — **молекулярная** (это газы и летучая жидкость!).…"}, "06.10": {"t": "Модуль 06 · 4. Аллотропные и формульные ловушки (95–100 баллов)", "x": "**Шаг 1.** **Классифицируем 6 спорных веществ: SiO2, CO2, белый фосфор, красный фосфор, NH4Cl, Al2O3.**\n**Шаг 2.** **SiO2 (оксид кремния(IV), кварц):** ковалентные полярные связи + входит в короткий список атомных → **атомная решётка** (немолекулярное строение).\n**Шаг 3.** **CO2 (оксид углерода(IV)):** кислотный оксид неметалла, не входит в список атомных → **молекулярная решётка** (молекулярное строение).\n**Шаг 4.** **Белый фосфор (P4):** молекулы из 4 атомов → **молекулярная решётка**; **красный фосфор:** полимерные цепи из атомов → **атомная решётка**.\n**Шаг 5.** **NH4Cl (хлорид аммония):** соль аммония → есть ионная связь между NH4^{+} и Cl^{−} → **ионная решётка** (немолекулярное строение!), несмотря на наличие ковалентных полярных связей внутри NH4^{+}.\n**Шаг 6.** **Al2O3 (оксид алюминия):** амфотерный оксид металла (металл + неметалл) → в ЕГЭ **ионная решётка** (немолекулярное строение)."}, "06.11": {"t": "Модуль 06 · Мост к КИМ (№ 4 КИМ ЕГЭ-2027)", "x": "**Как спрашивают:** Выберите два вещества немолекулярного строения (или: с атомной / молекулярной / ионной кристаллической решёткой).\n**На чём ловят:** Многие отсекают SiO2, алмаз или Fe, когда ищут «немолекулярное строение», ошибочно думая, что немолекулярное = только ионное. Другая частая ошибка — отнести NH4Cl или C2H5ONa к молекулярным.\n**Как читать:** Алгоритм за 3 секунды: 1) Это простое вещество-металл? → **металлическая**. 2) Есть ионная связь (соль, основание, основной/амфотерный оксид металла кроме CrO3/Mn2O7, соль аммония/амина, алкоголят/фенолят)? → **ионная**. 3) Входит в короткий список C(алм/граф), Si, B, Ge, P(красн), SiO2, SiC, BN? → **атомная**. 4) Всё остальное → **молекулярная**!"}, "07": {"t": "Модуль 07. Как тип кристаллической решётки предсказывает свойства вещества", "x": "Физические свойства вещества — прямое следствие прочности связей между узлами его решётки. Зная тип кристаллической решётки, ты без зазубривания предскажешь температуру плавления, твёрдость, летучесть, хрупкость и электропроводность вещества."}, "07.1": {"t": "Модуль 07 · Главная мысль.", "x": "Физические свойства вещества — прямое следствие прочности связей между узлами его решётки. Зная тип кристаллической решётки, ты без зазубривания предскажешь температуру плавления, твёрдость, летучесть, хрупкость и электропроводность вещества."}, "07.3": {"t": "Модуль 07 · 1. Сводная карта: как решётка управляет свойствами", "x": "• ****Температуры плавления и кипения**** — Низкие (часто газы, жидкости, легкоплавкие кристаллы); Очень высокие (обычно > 1000–3500 °C); Высокие (обычно 300–2500 °C); От низких (Hg, Na) до сверхвысоких (W, Fe); В молекулярной рвутся слабые силы Ван-дер-Ваальса; в атомной и ионной — прочные химические связи\n• ****Твёрдость и механика**** — Мягкие, хрупкие, легко растираются; Очень твёрдые, прочные (*исключение — графит*); Твёрдые, но **хрупкие** при ударе; **Пластичные**, ковкие, тянутся в проволоку; Сдвиг слоёв в ионном кристалле даёт отталкивание одноимённых ионов; в металле слои «смазывает» электронный газ\n• ****Летучесть и запах**** — **Летучие**, многие имеют запах (I2, NH3, эфиры); Нелетучие, без запаха; Нелетучие, без запаха; Нелетучие (кроме паров Hg), без запаха; Молекулы легко отрываются от поверхности кристалла из-за слабого межмолекулярного притяжения…"}, "07.5": {"t": "Модуль 07 · 2. Четыре особых случая на 95–100 баллов", "x": "• **1. Графит — атомная решётка, но мягкий и электропроводный.** В алмазе каждый атом углерода связан четырьмя прочными связями в жёсткий трёхмерный тетраэдр — отсюда рекордная твёрдость и отсутствие проводимости. В графите атомы углерода образуют плоские шестиугольные слои (sp²-гибридизация). Внутри слоя связи сверхпрочные (поэтому графит тугоплавок, как и положено атомной решётке!), а **между слоями** действуют слабые силы Ван-дер-Ваальса — слои легко соскальзывают (оставляя след карандаша на бумаге). При этом по каждому слою свободно бегают общие π-электроны, поэтому графит проводит электрический ток.\n• **2. Твёрдая соль vs расплав и раствор соли.** На экзамене часто ловят на формулировке «проводит электрический ток в твёрдом состоянии». Соли (NaCl, KNO3) в **твёрдом** виде ток **не проводят** — ионы зажаты в узлах решётки. Но стоит расплавить соль или растворить её в воде, как ионы освобождаются и начинают переносить ток.…"}, "07.8": {"t": "Модуль 07 · Маркер молекулярной решётки в тексте задания", "x": "Осторожно со словом «возгонка» (сублимация — переход сразу из твёрдого состояния в газ, минуя жидкость)! Способностью легко возгоняться обладают вещества с **молекулярной** решёткой: сухой лёд (CO2), иод (I2), нафталин, камфора. У веществ с атомной и ионной решёткой при обычном давлении лёгкой возгонки нет."}, "08": {"t": "Модуль 08. Алгоритм решения задания 4 ЕГЭ-2027: двойной фильтр и разбор ловушек", "x": "Задание № 4 оценивается в **1 первичный балл** (порядок двух цифр не важен, но любая ошибка даёт 0). Чтобы решать его со 100% точностью за 40 секунд, выписывай **формулу каждого из пяти веществ** (переводя тривиальные и органические названия!), отдельно проверяй **Фильтр 1 (решётка/строение)** и **Фильтр 2 (все виды связей)**."}, "08.1": {"t": "Модуль 08 · Главная мысль.", "x": "Задание № 4 оценивается в **1 первичный балл** (порядок двух цифр не важен, но любая ошибка даёт 0). Чтобы решать его со 100% точностью за 40 секунд, выписывай **формулу каждого из пяти веществ** (переводя тривиальные и органические названия!), отдельно проверяй **Фильтр 1 (решётка/строение)** и **Фильтр 2 (все виды связей)**."}, "08.3": {"t": "Модуль 08 · Двойной фильтр задания № 4: определяем решётку и связи", "x": "• Это простое вещество-металл или сплав (Fe, Cu, Na, Al, латунь)?\n• Да → **Металлическая решётка (немолекулярное строение) · Металлическая связь** (В узлах — атомы-ионы металла, между ними обобществлённый «электронный газ». Других связей нет.)\n• Нет → Есть ли в веществе металл (кроме CrO3, Mn2O7) ИЛИ катион аммония NH₄⁺ / алкиламмония R–NH₃⁺?\n• Да → **Ионная решётка (немолекулярное строение) · Ионная связь + проверяй сложные ионы!** (Если оба иона одноатомные (NaCl, CaCl2, MgO, Al2O3) — только ионная. Если есть сложный ион (OH⁻, SO₄²⁻, NO₃⁻, NH₄⁺) — добавляется ковалентная полярная. Если есть O–O, S–S, C≡C или цепь C–C (Na2O2, FeS2, CaC2, C2H5ONa, CH3COONa) — добавляется ковалентная неполярная!)\n• Нет → Вещество входит в короткий список атомных: алмаз, графит, Si, B, Ge, красный/чёрный P, SiO2, SiC, BN?…"}, "08.5": {"t": "Модуль 08 · 2. Разбор 7 типовых заданий № 4 ЕГЭ-2027 (включая демоверсию)", "x": "**Шаг 1.** **Кейс 1 (Демоверсия ФИПИ ЕГЭ-2027).** *Выберите два вещества с ковалентной полярной химической связью, которые имеют ионную кристаллическую решётку: 1) хлорид кальция, 2) оксид фосфора(V), 3) этилат натрия, 4) аммиак, 5) гидроксид калия.*\n**Разбор:** Переводим в формулы: 1) CaCl2 — ионная решётка, но только ионная связь (нет ковалентной) → вычёркиваем. 2) P2O5 (P4O10) — ковалентная полярная связь, но молекулярная решётка → вычёркиваем. 3) C2H5ONa — ионная решётка (есть O^{−} Na^{+}) + ковалентные полярные C−H, C−O (и неполярная C−C) → **подходит (3)**. 4) NH3 — молекулярная решётка → вычёркиваем. 5) KOH — ионная решётка + ковалентная полярная O−H внутри OH^{−} → **подходит (5)**. **Ответ: 35.**…"}, "08.7": {"t": "Модуль 08 · Таблица-шпаргалка тривиальных названий в задании № 4", "x": "• **Кварц, кремнезём, речной песок** — Формула: SiO2; Решётка: Атомная; Главные связи / особенности: Ковалентная полярная; немолекулярное строение\n• **Карборунд** — Формула: SiC; Решётка: Атомная; Главные связи / особенности: Ковалентная полярная; немолекулярное строение\n• **Пирит (железный колчедан)** — Формула: FeS2; Решётка: Ионная; Главные связи / особенности: Ионная + **ковалентная неполярная** (S−S)\n• **Нашатырь** — Формула: NH4Cl; Решётка: Ионная; Главные связи / особенности: Ионная + ковалентная полярная + **Д-А механизм**\n• **Аммиачная селитра** — Формула: NH4NO3; Решётка: Ионная; Главные связи / особенности: Ионная + ковалентная полярная + **Д-А механизм** (в обоих ионах!)\n• **Едкий натр / едкое кали** — Формула: NaOH / KOH; Решётка: Ионная; Главные связи / особенности: Ионная + ковалентная полярная (O−H)…"}, "08.8": {"t": "Модуль 08 · Чек-лист последних 10 секунд на экзамене", "x": "Последняя проверка перед записью ответа в бланк:\n1. Прочитай условие ещё раз: нужно «**с** ковалентной связью» (может быть и ионная рядом!) или «**только** с ковалентной связью»?\n2. Выписаны ли ровно **две** цифры? В задании № 4 всегда ровно 2 ответа; порядок записи цифр значения не имеет (35 и 53 равноценны), но лишняя или пропущенная цифра сразу обнуляет балл."}}, "_kt": "Задание 4 ЕГЭ по химии: химическая связь и кристаллические решётки с нуля до 100 баллов", "_mods": {"01": "Зачем атомы соединяются: электроотрицательность и карта связей", "02": "Ковалентная связь: обменный и донорно-акцепторный механизмы", "03": "Характеристики ковалентной связи: σ- и π-связи, длина, энергия и полярность молекул", "04": "Ионная и металлическая связь: от электростатики до «электронного газа»", "05": "Водородная связь и межмолекулярные взаимодействия", "06": "Молекулярное и немолекулярное строение: четыре типа кристаллических решёток", "07": "Как тип кристаллической решётки предсказывает свойства вещества", "08": "Алгоритм решения задания 4 ЕГЭ-2027: двойной фильтр и разбор ловушек"}, "_skm": {"eo_map": ["01"], "cov_mech": ["02"], "cov_props": ["03"], "ion_met": ["04"], "h_bond": ["05"], "lattices": ["06"], "phys_props": ["07"], "double_filter": ["08"]}, "_fig": []};
